(window.__docs=window.__docs||{})["24-2023-tt-nhnn"]={"id":"24-2023-tt-nhnn","nhom":"chap-thuan","nhom_con":null,"loai":"Thông tư","so_hieu":"24/2023/TT-NHNN","ngay":"29/12/2023","tieu_de":"Sửa đổi, bổ sung một số điều của các Thông tư liên quan đến việc nộp, xuất trình, cung cấp thông tin, giấy tờ về dân cư khi thực hiện thủ tục hành chính trong lĩnh vực thành lập và hoạt động ngân hàng","can_cu":[["p","<i>Căn cứ Luật Ngân hàng Nhà nước Việt Nam ngày 16 tháng 6 năm 2010;</i>",""],["p","<i>Căn cứ Luật Các tổ chức tín dụng ngày 16 tháng 6 năm 2010; Luật sửa đổi, bổ sung một số điều của Luật Các tổ chức tín dụng ngày 20 tháng 11 năm 2017;</i>",""],["p","<i>Căn cứ Nghị định số 102/2022/NĐ-CP ngày 12 tháng 12 năm 2022 của Chính phủ quy định chức năng, nhiệm vụ, quyền hạn và cơ cấu tổ chức của Ngân hàng Nhà nước Việt Nam;</i>",""],["p","<i>Theo đề nghị của Chánh Thanh tra, giám sát ngân hàng;</i>",""],["p","<i>Thống đốc Ngân hàng Nhà nước Việt Nam ban hành Thông tư <b>sửa đổi, bổ sung một số điều của các Thông tư liên quan đến việc nộp, xuất trình, cung cấp thông tin, giấy tờ về dân cư khi thực hiện thủ tục hành chính trong lĩnh vực thành lập và hoạt động ngân hàng</b>. </i>",""]],"lich_su":[],"dong_thoi_gian":[],"chuong":[{"id":"c1","title":"","articles":[{"id":"dieu-1","so":"1","ten":"Sửa đổi, bổ sung, bãi bỏ, thay thế một số điểm, phụ lục của Thông tư số 31/2012/TT-NHNN ngày 26 tháng 11 năm 2012 của Thống đốc Ngân hàng Nhà nước Việt Nam quy định về ngân hàng hợp tác xã","nd":[["p","1. Sửa đổi, bổ sung điểm a khoản 5 Điều 9 như sau:","k"],["p","“a) Danh sách các thành viên tham gia góp vốn vào ngân hàng hợp tác xã, trong đó có các nội dung chủ yếu sau:",""],["p","- Tên và địa điểm đặt trụ sở chính; Số Giấy phép thành lập hoặc Giấy chứng nhận đăng ký doanh nghiệp hoặc văn bản tương đương; số vốn góp, tỷ lệ vốn góp, thời hạn góp vốn;","g"],["p","- Họ và tên; nơi ở hiện tại (trường hợp khác nơi đăng ký thường trú, tạm trú); số Chứng minh nhân dân hoặc số định danh cá nhân đối với cá nhân là người đại diện theo pháp luật, người đại diện vốn góp của thành viên;”.","g"],["p","2. Bãi bỏ điểm c khoản 4 và điểm g khoản 5 Điều 9.","k"],["p","3. Thay thế Phụ lục số 01, Phụ lục số 02 bằng Phụ lục số 01, Phụ lục số 02 ban hành kèm theo Thông tư này.","k"]]},{"id":"dieu-2","so":"2","ten":"Thay thế một số phụ lục của Thông tư số 01/2023/TT-NHNN ngày 01 tháng 3 năm 2023 sửa đổi, bổ sung một số điều của Thông tư số 04/2015/TT-NHNN ngày 31 / 3 / 2015 của Thống đốc Ngân hàng N hà nước Việt Nam quy định về quỹ tín dụng nhân dân","nd":[["p","Thay thế Phụ lục số 01, Phụ lục số 02, Phụ lục số 03, Phụ lục số 04 bằng Phụ lục số 03, Phụ lục số 04, Phụ lục số 05, Phụ lục số 06 ban hành kèm theo Thông tư này.",""]]},{"id":"dieu-3","so":"3","ten":"Sửa đổi, bổ sung, bãi bỏ, thay thế một số khoản, điểm, phụ lục của Thông tư số 0 3 /2018/TT - NHNN ngày 23 tháng 02 năm 2018 của Thống đốc Ngân hàng Nhà nước Việt Nam quy định về cấp Giấy phép, tổ chức và hoạt động của tổ chức tài chính vi mô","nd":[["p","1. Sửa đổi, bổ sung điểm d(iii) và d(iv) khoản 1 Điều 9 như sau:","k"],["p","a) Sửa đổi, bổ sung điểm d(iii) như sau:","d"],["p","“(iii) Bản kê khai người có liên quan với nhân sự dự kiến bầu, bổ nhiệm theo mẫu tại Phụ lục số 08a ban hành kèm theo Thông tư này;”;",""],["p","b) Sửa đổi, bổ sung điểm d(iv) như sau:","d"],["p","“(iv) Bản sao hộ chiếu hoặc giấy tờ có giá trị thay thế hộ chiếu đối với cá nhân không có quốc tịch Việt Nam;”.",""],["p","2. Sửa đổi, bổ sung điểm c, điểm d(v) và điểm đ(i) khoản 1 Điều 11 như sau:","k"],["p","a) Sửa đổi, bổ sung điểm c như sau:","d"],["p","“c) Danh sách thành viên sáng lập do Trưởng Ban trù bị ký, trong đó bao gồm các nội dung:",""],["p","(i) Đối với thành viên sáng lập là cá nhân: Họ và tên; ngày, tháng, năm sinh; số Chứng minh nhân dân hoặc số định danh cá nhân;",""],["p","(ii) Đối với thành viên sáng lập là tổ chức: Tên tổ chức, số Giấy phép thành lập hoặc Giấy chứng nhận đăng ký doanh nghiệp hoặc văn bản tương đương; số Chứng minh nhân dân hoặc số định danh cá nhân (đối với cá nhân có quốc tịch Việt Nam), số hộ chiếu hoặc giấy tờ có giá trị thay thế hộ chiếu, ngày cấp, nơi cấp, quốc tịch/các quốc tịch (đối với cá nhân không có quốc tịch Việt Nam) của người đại diện hợp pháp của tổ chức tham gia góp vốn thành lập tổ chức tài chính vi mô và người đại diện vốn góp của tổ chức đó tại tổ chức tài chính vi mô;",""],["p","(iii) Mức vốn góp (ghi rõ số vốn bằng đồng Việt Nam, bằng tài sản khác và tỷ lệ góp vốn của từng thành viên);",""],["p","(iv) Phương án góp vốn (nêu rõ phương thức, tiến độ góp vốn);”;",""],["p","b) Sửa đổi, bổ sung điểm d(v) như sau:","d"],["p","“(v) Bản sao hộ chiếu hoặc giấy tờ có giá trị thay thế hộ chiếu (đối với cá nhân không có quốc tịch Việt Nam) của người đại diện hợp pháp của tổ chức tham gia góp vốn thành lập tổ chức tài chính vi mô và người đại diện vốn góp của tổ chức đó tại tổ chức tài chính vi mô;”;",""],["p","c) Sửa đổi, bổ sung điểm đ(i) như sau:","d"],["p","“(i) Sơ yếu lý lịch, bản kê khai người có liên quan theo mẫu tại Phụ lục số 02, Phụ lục số 08b ban hành kèm theo Thông tư này;”.",""],["p","3. Sửa đổi, bổ sung khoản 5 Điều 24 như sau:","k"],["p","“5. Bản kê khai người có liên quan với nhân sự dự kiến bầu, bổ nhiệm theo mẫu tại Phụ lục số 08a ban hành kèm theo Thông tư này”.",""],["p","4. Bãi bỏ điểm đ(iii) khoản 1 Điều 11 và Phụ lục số 04.","k"],["p","5. Thay thế Phụ lục số 02 bằng Phụ lục số 07 ban hành kèm theo Thông tư này.","k"],["p","6. Bổ sung Phụ lục số 08a và Phụ lục số 08b ban hành kèm theo Thông tư này.","k"]]},{"id":"dieu-4","so":"4","ten":"Thay thế một số phụ lục của Thông tư số 22/2022/TT-NHNN ngày 30 tháng 12 năm 2022 sửa đổi, bổ sung một số Điều của T hông tư số 05/2018/ TT - NHNN ngày 12 tháng 03 năm 2018 của T hống đốc N gân hàng N hà nước V iệt N am quy định về hồ sơ, trình tự, thủ tục chấp thuận những thay đổi, danh sách dự kiến bầu, bổ nhiệm nhân sự của tổ chức tín dụng là hợp tác xã","nd":[["p","Thay thế Phụ lục số 08, Phụ lục số 09 bằng Phụ lục số 09, Phụ lục số 10 ban hành kèm theo Thông tư này.",""]]},{"id":"dieu-5","so":"5","ten":"Thay thế, bãi bỏ một số cụm từ, phụ lục của Thông tư số 10 /2018/TT - NHNN ngày 09 tháng 4 năm 2018 của Thống đốc Ngân hàng Nhà nước Việt Nam quy định hồ sơ, trình tự, thủ tục chấp thuận những thay đổi của tổ chức tài chính vi mô","nd":[["p","1. Thay thế cụm từ “Bản sao Giấy chứng minh nhân dân hoặc thẻ căn cước công dân hoặc hộ chiếu của người đại diện hợp pháp của tổ chức và người đại diện vốn góp tại tổ chức tài chính vi mô” bằng cụm từ “Bản sao hộ chiếu hoặc giấy tờ có giá trị thay thế hộ chiếu (đối với cá nhân không có quốc tịch Việt Nam) của người đại diện hợp pháp của tổ chức và người đại diện vốn góp tại tổ chức tài chính vi mô” tại điểm đ(i) khoản 1 Điều 11.","k"],["p","2. Bãi bỏ cụm từ “Bản sao Giấy chứng minh nhân dân hoặc thẻ căn cước công dân hoặc hộ chiếu” tại điểm đ(ii) khoản 1 Điều 11.","k"],["p","3. Thay thế Phụ lục số 01, Phụ lục số 02 bằng Phụ lục số 11, Phụ lục số 12 ban hành kèm theo Thông tư này.","k"]]},{"id":"dieu-6","so":"6","ten":"Sửa đổi, bổ sung, thay thế một số điểm, cụm từ, phụ lục của Thông tư số 23 /2018/TT-NHNN ngày 14 tháng 9 năm 2018 của Thống đốc Ngân hàng Nhà nước Việt Nam quy định về tổ chức lại, thu hồi Giấy phép và thanh lý tài sản của quỹ tín dụng nhân dân","nd":[["p","1. Sửa đổi, bổ sung điểm g(ii) khoản 2 Điều 11 như sau:","k"],["p","“ii) Số Chứng minh nhân dân hoặc số định danh cá nhân đối với thành viên là cá nhân, người đại diện hộ gia đình; số Giấy chứng nhận đăng ký doanh nghiệp hoặc mã số doanh nghiệp đối với thành viên là pháp nhân;”.",""],["p","2. Thay thế cụm từ “địa chỉ thường trú” bằng cụm từ “nơi ở hiện tại (trường hợp khác nơi đăng ký thường trú, tạm trú)”, thay thế cụm từ “số Chứng minh nhân dân hoặc số thẻ Căn cước công dân hoặc số hộ chiếu” bằng cụm từ “số Chứng minh nhân dân hoặc số định danh cá nhân” tại điểm I.6 Mục B Phụ lục 01.","k"],["p","3. Thay thế Phụ lục 02, Phụ lục 03 bằng Phụ lục số 13, Phụ lục số 14 ban hành kèm theo Thông tư này.","k"]]},{"id":"dieu-7","so":"7","ten":"Sửa đổi, bổ sung, thay thế một số điểm, phụ lục của Thông tư 25/2017/TT-NHNN ngày 29 tháng 12 năm 2017 của Thống đốc Ngân hàng Nhà nước Việt Nam quy định về hồ sơ, trình tự, thủ tục chấp thuận những thay đổi của tổ chức tín dụng phi ngân hàng","nd":[["p","<b>1. Sửa đổi, bổ sung điểm đ(i) và điểm đ(ii) khoản 1 Điều 9 như sau:</b>",""],["p","“(i) Đối với cá nhân: Họ và tên; số Chứng minh nhân dân hoặc số định danh cá nhân (đối với cá nhân có quốc tịch Việt Nam); số hộ chiếu hoặc giấy tờ có giá trị thay thế hộ chiếu, ngày cấp, nơi cấp (đối với cá nhân không có quốc tịch Việt Nam);",""],["p","(ii) Đối với tổ chức: Tên tổ chức, địa chỉ trụ sở chính, số Giấy phép thành lập hoặc số Giấy chứng nhận đăng ký doanh nghiệp hoặc văn bản tương đương, ngày cấp, nơi cấp; họ và tên, số Chứng minh nhân dân hoặc số định danh cá nhân (đối với cá nhân có quốc tịch Việt Nam), số hộ chiếu hoặc giấy tờ có giá trị thay thế hộ chiếu, ngày cấp, nơi cấp (đối với cá nhân không có quốc tịch Việt Nam) của người đại diện hợp pháp của tổ chức;”.",""],["p","<b>2. Sửa đổi, bổ sung điểm c(ii) khoản 3 Điều 10 như sau:</b>",""],["p","“(ii) Thông tin của bên bán, bên chuyển nhượng, bên mua, bên nhận chuyển nhượng: Tên tổ chức, địa chỉ trụ sở chính, số Giấy phép thành lập hoặc số Giấy chứng nhận đăng ký doanh nghiệp hoặc văn bản tương đương, ngày cấp, nơi cấp; họ và tên, số Chứng minh nhân dân hoặc số định danh cá nhân (đối với cá nhân có quốc tịch Việt Nam), số hộ chiếu hoặc giấy tờ có giá trị thay thế hộ chiếu, ngày cấp, nơi cấp (đối với cá nhân không có quốc tịch Việt Nam) của người đại diện hợp pháp của tổ chức;”.",""],["p","3. Sửa đổi, bổ sung điểm a(i), điểm b(i), điểm b(ii) khoản 1 và điểm b(i) khoản 2 Điều 11 như sau:","k"],["p","a) Sửa đổi, bổ sung điểm a(i) khoản 1 như sau:","d"],["p","“(i) Thông tin về bên bán, bên chuyển nhượng:",""],["p","- Đối với cá nhân: Họ và tên; số Chứng minh nhân dân hoặc số định danh cá nhân (đối với cá nhân có quốc tịch Việt Nam); số hộ chiếu hoặc giấy tờ có giá trị thay thế hộ chiếu, ngày cấp, nơi cấp (đối với cá nhân không có quốc tịch Việt Nam);","g"],["p","- Đối với tổ chức: Tên tổ chức, địa chỉ trụ sở chính, số Giấy phép thành lập hoặc số Giấy chứng nhận đăng ký doanh nghiệp hoặc văn bản tương đương, ngày cấp, nơi cấp; họ và tên, số Chứng minh nhân dân hoặc số định danh cá nhân (đối với cá nhân có quốc tịch Việt Nam), số hộ chiếu hoặc giấy tờ có giá trị thay thế hộ chiếu, ngày cấp, nơi cấp (đối với cá nhân không có quốc tịch Việt Nam) của người đại diện hợp pháp của tổ chức;”;","g"],["p","b) Sửa đổi, bổ sung điểm b(i), điểm b(ii) khoản 1 như sau:","d"],["p","“(i) Đối với cá nhân: Họ và tên; số Chứng minh nhân dân hoặc số định danh cá nhân (đối với cá nhân có quốc tịch Việt Nam); số hộ chiếu hoặc giấy tờ có giá trị thay thế hộ chiếu, ngày cấp, nơi cấp (đối với cá nhân không có quốc tịch Việt Nam).",""],["p","(ii) Đối với tổ chức: Tên tổ chức, địa chỉ trụ sở chính, số Giấy phép thành lập hoặc số Giấy chứng nhận đăng ký doanh nghiệp hoặc văn bản tương đương, ngày cấp, nơi cấp; họ và tên, số Chứng minh nhân dân hoặc số định danh cá nhân (đối với cá nhân có quốc tịch Việt Nam), số hộ chiếu hoặc giấy tờ có giá trị thay thế hộ chiếu, ngày cấp, nơi cấp (đối với cá nhân không có quốc tịch Việt Nam) của người đại diện hợp pháp của tổ chức;”;",""],["p","c) Sửa đổi, bổ sung điểm b(i) khoản 2 như sau:","d"],["p","“(i) Thông tin về bên bán, bên mua, bên chuyển nhượng và bên nhận chuyển nhượng cổ phần:",""],["p","- Đối với cá nhân: Họ và tên; số Chứng minh nhân dân hoặc số định danh cá nhân (đối với cá nhân có quốc tịch Việt Nam); số hộ chiếu hoặc giấy tờ có giá trị thay thế hộ chiếu, ngày cấp, nơi cấp (đối với cá nhân không có quốc tịch Việt Nam);","g"],["p","- Đối với tổ chức: Tên tổ chức, địa chỉ trụ sở chính, số Giấy phép thành lập hoặc số Giấy chứng nhận đăng ký doanh nghiệp hoặc văn bản tương đương, ngày cấp, nơi cấp; họ và tên, số Chứng minh nhân dân hoặc số định danh cá nhân (đối với cá nhân có quốc tịch Việt Nam), số hộ chiếu hoặc giấy tờ có giá trị thay thế hộ chiếu, ngày cấp, nơi cấp (đối với cá nhân không có quốc tịch Việt Nam) của người đại diện hợp pháp của tổ chức;”.","g"],["p","4. Thay thế Phụ lục bằng Phụ lục số 15 ban hành kèm theo Thông tư này.","k"]]},{"id":"dieu-8","so":"8","ten":"Sửa đổi, bổ sung, thay thế một số điểm, phụ lục của Thông tư số 22/2018/TT-NHNN ngày 05 tháng 9 năm 2018 của Thống đốc Ngân hàng Nhà nước Việt Nam hướng dẫn về thủ tục, hồ sơ chấp thuận danh sách dự kiến nhân sự của ngân hàng thương mại, tổ chức tín dụng phi ngân hàng và chi nhánh ngân hàng nước ngoài","nd":[["p","1. Sửa đổi, bổ sung điểm b khoản 1 Điều 7 như sau:","k"],["p","“b) Họ và tên; chức danh và đơn vị công tác hiện tại; số Chứng minh nhân dân hoặc số định danh cá nhân (đối với cá nhân có quốc tịch Việt Nam), số hộ chiếu hoặc giấy tờ có giá trị thay thế hộ chiếu, ngày cấp, nơi cấp (đối với cá nhân không có quốc tịch Việt Nam) của Tổng giám đốc (Giám đốc) dự kiến được bổ nhiệm;”.",""],["p","2. Thay thế Phụ lục số 01, Phụ lục số 02 bằng Phụ lục số 16, Phụ lục số 17 ban hành kèm theo Thông tư này.","k"]]},{"id":"dieu-9","so":"9","ten":"Trách nhiệm tổ chức thực hiện","nd":[["p","Chánh Văn phòng, Chánh Thanh tra, giám sát ngân hàng, Thủ trưởng các đơn vị thuộc Ngân hàng Nhà nước Việt Nam, tổ chức tín dụng, chi nhánh ngân hàng nước ngoài và tổ chức, cá nhân có liên quan chịu trách nhiệm tổ chức thực hiện Thông tư này.",""]]},{"id":"dieu-10","so":"10","ten":"Điều khoản thi hành","nd":[["p","1. Thông tư này có hiệu lực từ ngày 01 tháng 3 năm 2024.","k"],["p","2. Đối với các hồ sơ Ngân hàng Nhà nước Việt Nam nhận được trước thời điểm Thông tư này có hiệu lực thi hành mà chưa được xem xét, xử lý thì tiếp tục thực hiện theo quy định tại Thông tư số 01/2023/TT-NHNN, Thông tư số 03/2018/TT-NHNN, Thông tư số 22/2022/TT-NHNN, Thông tư số 10/2018/TT-NHNN, Thông tư số 23/2018/TT-NHNN, Thông tư 25/2017/TT-NHNN, Thông tư số 22/2018/TT-NHNN.","k"],["p","3. Thông tư này bãi bỏ khoản 13 Điều 2 Thông tư số 13/2019/TT-NHNN ngày 21 tháng 8 năm 2019 của Thống đốc Ngân hàng Nhà nước Việt Nam sửa đổi, bổ sung một số điều của các Thông tư có liên quan đến việc cấp Giấy phép, tổ chức và hoạt động của tổ chức tín dụng, chi nhánh ngân hàng nước ngoài.","k"],["p","<b><i>Nơi nhận: THỐNG ĐỐC</i></b>",""],["p","<i>- Văn phòng Chính phủ;</i>","g"],["p","<i>- Bộ Tư pháp (để kiểm tra);</i>","g"],["p","<i>- Ban Lãnh đạo NHNN;</i>","g"],["p","<i>- Thủ trưởng các đơn vị thuộc NHNN;</i>","g"],["p","<i>- Các ngân hàng thương mại;</i>","g"],["p","<i>- Các tổ chức tín dụng phi ngân hàng;</i>","g"],["p","<i>- Các chi nhánh ngân hàng nước ngoài;</i>","g"],["p","<i>- Ngân hàng hợp tác xã;</i>","g"],["p","<i>- Các quỹ tín dụng nhân dân;</i>","g"],["p","<i>- Các tổ chức tài chính vi mô;</i>","g"],["p","<i>- Công báo;</i>","g"],["p","<i>- Cổng thông tin điện tử NHNN;</i>","g"],["p","<i>- Lưu: VP, Vụ PC, TTGSNH3.</i>","g"],["p","<b>DANH MỤC PHỤ LỤC</b> <i>(Ban hành kèm theo Thông tư số … /202 3 /TT- NHNN ngày … tháng … năm 202 3 của Thống đốc Ngân hàng Nhà nước Việt Nam )</i>",""],["t","<table><tr><td><b>STT</b></td><td><b>Tên Phụ lục</b></td><td><b>Ký hiệu</b></td><td><b>Ghi chú</b></td></tr><tr><td>1</td><td><b>Mẫu Sơ yếu lý lịch</b></td><td>Phụ lục số 01</td><td rowspan=\"2\">Thay thế Phụ lục của Thông tư số 31/2012/TT-NHNN</td></tr><tr><td>2</td><td><b>Bảng kê khai người có liên quan</b></td><td>Phụ lục số 02</td></tr><tr><td>3</td><td><b>Mẫu đơn tham gia thành viên đối với cá nhân</b></td><td>Phụ lục số 03</td><td rowspan=\"4\">Thay thế Phụ lục của Thông tư số 01/2023/TT-NHNN</td></tr><tr><td>4</td><td><b>Mẫu đơn tham gia thành viên đối với hộ gia đình</b></td><td>Phụ lục số 04</td></tr><tr><td>5</td><td><b>Mẫu đơn tham gia thành viên đối với pháp nhân</b></td><td>Phụ lục số 05</td></tr><tr><td>6</td><td><b>Mẫu Sơ yếu lý lịch</b></td><td>Phụ lục số 06</td></tr><tr><td>7</td><td><b>Mẫu Sơ yếu lý lịch</b></td><td>Phụ lục số 07</td><td rowspan=\"3\">Thay thế Phụ lục của Thông tư số 03/2018/TT-NHNN</td></tr><tr><td>8</td><td><b>Bảng kê khai người có liên quan  (sử dụng khi đề nghị chấp thuận danh sách nhân sự dự kiến)</b></td><td>Phụ lục số 08a</td></tr><tr><td>9</td><td><b>Bảng kê khai người có liên quan  (sử dụng khi đề nghị xem xét điều kiện thành viên góp vốn là cá nhân)</b></td><td>Phụ lục số 08b</td></tr><tr><td>10</td><td><b>Mẫu Sơ yếu lý lịch</b></td><td>Phụ lục số 09</td><td rowspan=\"2\">Thay thế Phụ lục của Thông tư số 22/2022/TT-NHNN</td></tr><tr><td>11</td><td><b>Bảng kê khai người có liên quan</b></td><td>Phụ lục số 10</td></tr><tr><td>12</td><td><b>Mẫu Sơ yếu lý lịch</b></td><td>Phụ lục số 11</td><td rowspan=\"2\">Thay thế Phụ lục của Thông tư số 10/2018/TT-NHNN</td></tr><tr><td>13</td><td><b>Bảng kê khai người có liên quan</b></td><td>Phụ lục số 12</td></tr><tr><td>14</td><td><b>Mẫu Sơ yếu lý lịch</b></td><td>Phụ lục số 13</td><td rowspan=\"2\">Thay thế Phụ lục của Thông tư số 23/2018/TT-NHNN</td></tr><tr><td>15</td><td><b>Bảng kê khai người có liên quan</b></td><td>Phụ lục số 14</td></tr><tr><td>16</td><td><b>Bảng kê khai người có liên quan</b></td><td>Phụ lục số 15</td><td>Thay thế Phụ lục của Thông tư số 25/2017/TT-NHNN</td></tr><tr><td>17</td><td><b>Mẫu Sơ yếu lý lịch</b></td><td>Phụ lục số 16</td><td rowspan=\"2\">Thay thế Phụ lục của Thông tư số 22/2018/TT-NHNN</td></tr><tr><td>18</td><td><b>Bảng kê khai người có liên quan</b></td><td>Phụ lục số 17</td></tr></table>",""]]}]},{"id":"c2","title":"Phụ lục số 01","articles":[{"id":"pl-2","so":"","ten":"","nd":[["p","<i>(Ban h à nh k è m theo Thông tư số</i> /<i>2023<i>/TT-NHNN </i> ngày / /2023 của </i>",""],["p","<i>Thống đốc Ngân hàng Nhà nước Việt Nam)</i>",""]]}],"phu_luc":true},{"id":"c3","title":"Phụ lục số 01 — Mẫu Sơ yếu lý lịch — CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM Độc lập - Tự do - Hạnh phúc","articles":[{"id":"pl-3","so":"","ten":"","nd":[["p","Ảnh màu (4x6) đóng dấu giáp lai của cơ quan xác nhận lý lịch",""],["p","<b>SƠ YẾU LÝ LỊCH</b>",""],["p","<b>1. Về bản thân</b>","k"],["p","- Họ và tên khai sinh.","g"],["p","- Họ và tên thường gọi.","g"],["p","- Bí danh (nếu có).","g"],["p","- Ngày, tháng, năm sinh.","g"],["p","- Số Chứng minh nhân dân hoặc số định danh cá nhân, nơi ở hiện tại (trường hợp khác nơi đăng ký thường trú, tạm trú) đối với cá nhân có quốc tịch Việt Nam.","g"],["p","- Số hộ chiếu hoặc giấy tờ có giá trị thay thế hộ chiếu, ngày cấp, nơi cấp, quốc tịch/các quốc tịch (nếu có), nơi ở hiện tại đối với cá nhân không có quốc tịch Việt Nam.","g"],["p","- Tên, địa chỉ pháp nhân; số vốn góp, tỷ lệ vốn góp (trường hợp là người đại diện vốn góp của pháp nhân). Trường hợp là người được cử làm đại diện phần vốn hỗ trợ của Nhà nước tại Ngân hàng hợp tác xã, phải có thêm thông tin về tỷ lệ vốn góp được đại diện.","g"],["p","<b>2. Trình độ học vấn:</b>","k"],["p","- Giáo dục phổ thông.","g"],["p","- Học hàm, học vị (nêu rõ tên, địa chỉ trường; chuyên ngành học; thời gian học; bằng cấp (liệt kê đầy đủ các bằng cấp).","g"],["p","<b>3. Quá trình công tác:</b>","k"],["p","- Nghề nghiệp, đơn vị, chức vụ công tác từ năm 18 tuổi đến nay(1):","g"],["t","<table><tr><td><b>STT</b></td><td><b>Thời gian (từ tháng/năm đến tháng/năm)(2)</b></td><td><b>Đơn vị công tác</b></td><td><b>Chức vụ</b></td><td><b>Lĩnh vực hoạt động của doanh nghiệp và nhiệm vụ được giao</b></td><td><b>Ghi chú(3)</b></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td></tr></table>",""],["p","- Khen thưởng, kỷ luật, trách nhiệm theo kết luận thanh tra dẫn đến việc tổ chức tín dụng, chi nhánh ngân hàng nước ngoài bị xử phạt vi phạm hành chính(4).","g"],["p","<b>4. Mối quan hệ</b>","k"],["t","<table><tr><td><b>STT</b></td><td><b>Họ và tên</b></td><td><b>Số Chứng minh nhân dân hoặc số định danh cá nhân </b></td><td><b>Mối quan hệ với người khai(5 )</b></td><td><b>Chức vụ tại ngân hàng hợp tác xã</b></td></tr><tr><td>1</td><td>Nguyễn Văn A</td><td></td><td>Anh ruột</td><td></td></tr><tr><td>2</td><td>Nguyễn Thị B</td><td></td><td>Vợ</td><td></td></tr></table>",""],["p","<b>5. Năng lực hành vi dân sự(6)</b>","k"],["p","<b>6. Cam kết trước pháp luật</b>","k"],["p","Tôi cam kết:",""],["p","- Không vi phạm các quy định của pháp luật trong lĩnh vực tiền tệ và ngân hàng.","g"],["p","- Đáp ứng tiêu chuẩn, điều kiện để giữ chức danh…………………. tại ngân hàng hợp tác xã.","g"],["p","- Thông báo cho ngân hàng hợp tác xã về bất kỳ thay đổi nào liên quan đến nội dung bản khai trên phát sinh trong thời gian Ngân hàng Nhà nước Việt Nam đang xem xét đề nghị của ngân hàng hợp tác xã.","g"],["p","- Các thông tin cá nhân tôi cung cấp cho ngân hàng hợp tác xã để trình Ngân hàng Nhà nước Việt Nam xem xét, chấp thuận dự kiến nhân sự là đúng sự thật.","g"],["p","Tôi xin chịu hoàn toàn trách nhiệm đối với bất kỳ thông tin nào không đúng với sự thật tại bản khai này.",""],["p","<i>..., ngày... tháng... năm .... </i><b>Người khai </b><i>(<i>Ký, ghi rõ họ tên</i>)<i>(7)</i></i>",""],["p","<b><i>Ghi chú:</i></b>",""],["p","<i>Người khai phải kê khai đầy đủ thông tin theo yêu cầu và chịu trách nhiệm trước pháp luật và tổ chức tín dụng là hợp tác xã về tính đầy đủ, chính xác, trung thực của hồ sơ, trường hợp không phát sinh thì ghi rõ không có.</i>",""],["p","<i>(1) Người khai phải kê khai đầy đủ công việc, đơn vị công tác, các chức vụ đã và đang nắm giữ.</i>",""],["p","<i>(2) Phải đảm bảo tính liên tục về mặt thời gian.</i>",""],["p","<i>(3) Ghi chú nếu đơn vị công tác thuộc các trường hợp sau:</i>",""],["p","(i) Doanh nghiệp mà Nhà nước sở hữu từ 50% vốn điều lệ trở lên;",""],["p","(ii) Đơn vị theo quy định tại điểm e khoản 2 Điều 33 Luật Các tổ chức tín dụng (đã sửa đổi, bổ sung);",""],["p","(iii) Đơn vị theo quy định tại điểm c, d khoản 1 Điều 33 Luật Các tổ chức tín dụng (đã sửa đổi, bổ sung).",""],["p","<i>(4) Ghi cụ thể nếu nhân sự thuộc trường hợp nêu tại điểm đ, h khoản 1 Điều 33 Luật Các tổ chức tín dụng (đã sửa đổi, bổ sung).</i>",""],["p","<i>(5) Căn cứ mối quan hệ thực tế của người có liên quan thuộc trường hợp cụ thể theo quy định tại khoản 28 Điều 4 Luật Các tổ chức tín dụng (đã sửa đổi, bổ sung) và quy định có liên quan để điền vào cột này.</i>",""],["p","<i>(6) Ghi cụ thể: Đầy đủ/Hạn chế/Mất năng lực hành vi dân sự.</i>",""],["p","<i>(7) Chữ ký phải được chứng thực theo quy định của pháp luật.</i>",""],["p","<i>Ngoài những nội dung cơ bản trên, người khai có thể bổ sung các nội dung khác nếu thấy cần thiết.</i>",""]]}],"phu_luc":true},{"id":"c4","title":"Phụ lục số 02","articles":[{"id":"pl-4","so":"","ten":"","nd":[["p","<i>(Ban hành kèm theo Thông tư số</i> /<i>2023<i>/TT-NHNN ngày / /2023 của </i></i>",""],["p","<i>Thống đốc Ngân hàng Nhà nước Việt Nam)</i>",""]]}],"phu_luc":true},{"id":"c5","title":"Phụ lục số 02 — Bảng kê khai người có liên quan — CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM Độc lập - Tự do - Hạnh phúc","articles":[{"id":"pl-5","so":"","ten":"","nd":[["p","<b>BẢNG KÊ KHAI NGƯỜI CÓ LIÊN QUAN</b>",""],["p","Kính gửi: Ngân hàng Nhà nước Việt Nam",""],["t","<table><tr><td rowspan=\"2\"><b>STT</b></td><td rowspan=\"2\"><b>Người khai và “người có liên quan” của người khai</b></td><td rowspan=\"2\"><b>Số CMND/</b><br><b>số định danh cá nhân/số Hộ chiếu; Số Giấy phép(1)</b></td><td rowspan=\"2\"><b>Mối quan hệ với người khai(2)</b></td><td colspan=\"2\"><b>Đã tham gia góp vốn tổ chức tín dụng</b></td><td rowspan=\"2\"><b>Số vốn góp tại ngân hàng hợp tác xã khi thành lập</b></td></tr><tr><td><b>Tên, địa chỉ tổ chức tín dụng</b></td><td><b>Tỷ lệ góp vốn điều lệ của tổ chức tín dụng (%)</b></td></tr><tr><td><b>I</b></td><td colspan=\"5\"><b>Tổ chức khai</b></td><td></td></tr><tr><td><b>1</b></td><td><b>Tổ chức A</b></td><td></td><td><b>Tổ chức khai</b></td><td></td><td></td><td></td></tr><tr><td><b>II.</b></td><td colspan=\"5\"><b>Người có liên quan/tổ chức có liên quan</b></td><td></td></tr><tr><td><b>1.</b></td><td><b>Nguyễn Văn A/</b><br><b>Tổ chức B</b></td><td></td><td><b>Giám đốc/</b><br><b>Công ty con</b></td><td></td><td></td><td></td></tr><tr><td>Tổng cộng</td><td></td><td></td><td></td><td></td><td>% (chi tiết từng tổ chức tín dụng)</td><td></td></tr></table>",""],["p","Tôi cam kết các thông tin cung cấp trên đây là đúng sự thật. Tôi xin chịu trách nhiệm trước pháp luật về tính đầy đủ và trung thực của các thông tin kê khai nêu trên.",""],["p","<i>...,ngày ... tháng ... năm …..</i> <b>Người khai(3)</b> <i>(Ký, ghi rõ họ tên)</i>",""],["p","<b><i>Ghi chú:</i></b>",""],["p","<i>(1) Số Chứng minh nhân dân hoặc số định danh cá nhân</i> đối với cá nhân có quốc tịch Việt Nam<i>; số hộ chiếu hoặc giấy tờ có giá trị thay thế hộ chiếu đối với cá nhân không có quốc tịch Việt Nam; Số </i>Giấy phép thành lập hoặc Giấy chứng nhận đăng ký doanh nghiệp hoặc văn bản tương đương đối với tổ chức<i>.</i>",""],["p","(2) <i>Căn cứ mối quan hệ thực tế của người có liên quan thuộc trường hợp cụ thể theo quy định tại khoản 28 Điều 4 Luật Các tổ chức tín dụng (đã sửa đổi, bổ sung) và quy định có liên quan để điền vào cột này</i>.",""],["p","(3) Chữ ký phải được chứng thực theo quy định của pháp luật. Người ký tên người khai là đại diện hợp pháp của tổ chức và đóng dấu..",""],["p","<b>Ngoài những nội dung tối thiểu nêu trên, người khai có thể bổ sung các nội dung khác nếu thấy cần thiết.</b>",""]]}],"phu_luc":true},{"id":"c6","title":"Phụ lục số 03","articles":[{"id":"pl-6","so":"","ten":"","nd":[["p","<i>(Ban hành kèm theo Thông tư số</i> /<i>2023<i>/TT-NHNN ngày / /2023 của </i></i>",""],["p","<i>Thống đốc Ngân hàng Nhà nước Việt Nam)</i>",""]]}],"phu_luc":true},{"id":"c7","title":"Phụ lục số 01 — Mẫu đơn tham gia thành viên đối với cá nhân — CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM Độc lập - Tự do - Hạnh phúc","articles":[{"id":"pl-7","so":"","ten":"","nd":[["p","<i>……., ngày….. tháng….. năm……</i>",""],["p","<b>ĐƠN ĐỀ NGHỊ THAM GIA THÀNH VIÊN (Đối với cá nhân)</b>",""],["p","Kính gửi: Hội đồng quản trị Quỹ tín dụng nhân dân………………………",""],["p","<b>1. Cá nhân đề nghị tham gia thành viên</b>","k"],["p","- Họ và tên <i>(tên đầy đủ và chính thức, ghi bằng chữ in hoa)</i>.","g"],["p","- Ngày, tháng, năm sinh.","g"],["p","- Số Chứng minh nhân dân hoặc số định danh cá nhân.","g"],["p","- Nơi ở hiện tại (trường hợp khác nơi đăng ký thường trú, tạm trú).","g"],["p","- Nghề nghiệp, nơi công tác và chức vụ hiện tại.","g"],["p","- Số điện thoại.","g"],["p","Sau khi nghiên cứu Điều lệ Quỹ tín dụng nhân dân ……. và các quy định của pháp luật có liên quan, tôi xin được đăng ký tham gia là thành viên của Quỹ tín dụng nhân dân ………… với số tiền góp vốn là ………………đồng.",""],["p","<b>2. Cam kết</b>","k"],["p","Tôi xin cam kết:",""],["p","a) Góp đủ vốn đã đăng ký và góp vốn đúng thời hạn theo quy định của Quỹ tín dụng nhân dân …………..;","d"],["p","b) Chịu trách nhiệm về tính hợp pháp của vốn góp vào Quỹ tín dụng nhân dân ………….;","d"],["p","c) Tuân thủ các quy định trong Điều lệ Quỹ tín dụng nhân dân……… và các quy định của pháp luật có liên quan;","d"],["p","d) Chịu trách nhiệm về tính trung thực, chính xác của những hồ sơ gửi kèm theo quy định.","d"],["p","<b>Người đề nghị tham gia thành viên </b><i>(Ký, ghi rõ họ, tên)</i>",""]]}],"phu_luc":true},{"id":"c8","title":"Phụ lục số 04","articles":[{"id":"pl-8","so":"","ten":"","nd":[["p","<i>(Ban hành kèm theo Thông tư số</i> /<i>2023<i>/TT-NHNN ngày / /2023 của </i></i>",""],["p","<i>Thống đốc Ngân hàng Nhà nước Việt Nam)</i>",""]]}],"phu_luc":true},{"id":"c9","title":"Phụ lục số 02 — Mẫu đơn tham gia thành viên đối với hộ gia đình — CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM Độc lập - Tự do - Hạnh phúc","articles":[{"id":"pl-9","so":"","ten":"","nd":[["p","<i>……., ngày….. tháng….. năm……</i>",""],["p","<b>ĐƠN ĐỀ NGHỊ THAM GIA THÀNH VIÊN (Đối với hộ gia đình)</b>",""],["p","Kính gửi: Hội đồng quản trị Quỹ tín dụng nhân dân……………………",""],["p","<b>1. Cá nhân đại diện hộ gia đình đề nghị tham gia thành viên</b>","k"],["p","- Họ và tên <i>(tên đầy đủ và chính thức, ghi bằng chữ in hoa).</i>","g"],["p","- Ngày, tháng, năm sinh.","g"],["p","- Số Chứng minh nhân dân hoặc số định danh cá nhân.","g"],["p","- Nơi ở hiện tại (trường hợp khác nơi đăng ký thường trú, tạm trú).","g"],["p","- Nghề nghiệp, nơi công tác và chức vụ hiện tại.","g"],["p","- Số điện thoại.","g"],["p","Sau khi nghiên cứu Điều lệ Quỹ tín dụng nhân dân….. và các quy định của pháp luật có liên quan, tôi được các thành viên trong hộ gia đình cử làm đại diện đăng ký tham gia làm thành viên của Quỹ tín dụng nhân dân …..….. với số tiền góp vốn là …..…..…..…. đồng.",""],["p","<b>2. Cam kết</b>","k"],["p","Chúng tôi xin cam kết:",""],["p","a) Góp đủ vốn đã đăng ký và góp vốn đúng thời hạn theo quy định của Quỹ tín dụng nhân dân…..…..;","d"],["p","b) Chịu trách nhiệm về tính hợp pháp của vốn góp vào Quỹ tín dụng nhân dân…..…..;","d"],["p","c) Tuân thủ các quy định trong Điều lệ Quỹ tín dụng nhân dân và các quy định của pháp luật có liên quan;","d"],["p","d) Chịu trách nhiệm về tính trung thực, chính xác của những hồ sơ gửi kèm theo quy định.","d"],["p","(Đính kèm văn bản ủy quyền của các thành viên trong hộ gia đình)",""],["p","<b>Người đại diện hộ gia đình </b><i>(Ký, ghi rõ họ, tên)</i>",""]]}],"phu_luc":true},{"id":"c10","title":"Phụ lục số 05","articles":[{"id":"pl-10","so":"","ten":"","nd":[["p","<i>(Ban h à nh k è m theo Thông tư số</i> /<i>2023<i>/TT-NHNN </i> ngày / /2023 của </i>",""],["p","<i>Thống đốc Ngân hàng Nhà nước Việt Nam)</i>",""]]}],"phu_luc":true},{"id":"c11","title":"Phụ lục số 03 — Mẫu đơn tham gia thành viên đối với pháp nhân — CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM Độc lập - Tự do - Hạnh phúc","articles":[{"id":"pl-11","so":"","ten":"","nd":[["p","<i>……., ngày….. tháng….. năm……</i>",""],["p","<b>ĐƠN ĐỀ NGHỊ THAM GIA THÀNH VIÊN (Đối với pháp nhân)</b>",""],["p","Kính gửi: Hội đồng quản trị Quỹ tín dụng nhân dân……………………",""],["p","<b>1. Pháp nhân đề nghị tham gia thành viên</b>","k"],["p","- Tên pháp nhân <i>(tên đầy đủ, tên giao dịch nếu có, ghi bằng chữ in hoa)</i>.","g"],["p","- Mã số doanh nghiệp hoặc số Quyết định thành lập hoặc số giấy tờ khác có giá trị tương đương, do... cấp ngày.... tháng….. năm ....","g"],["p","- Vốn điều lệ.","g"],["p","- Địa chỉ trụ sở chính.","g"],["p","- Số điện thoại. Số Fax.","g"],["p","<b>2. Người đại diện theo pháp luật</b>","k"],["p","- Họ và tên <i>(tên đầy đủ và chính thức, ghi bằng chữ in hoa)</i>.","g"],["p","- Ngày, tháng, năm sinh.","g"],["p","- Số Chứng minh nhân dân hoặc số định danh cá nhân.","g"],["p","- Nơi ở hiện tại (trường hợp khác nơi đăng ký thường trú, tạm trú).","g"],["p","- Chức vụ đang đảm nhiệm.","g"],["p","- Số điện thoại.","g"],["p","<b>3. Người đại diện theo ủy quyền tại quỹ tín dụng nhân dân</b>","k"],["p","- Họ và tên <i>(tên đầy đủ và chính thức, ghi bằng chữ in hoa)</i>.","g"],["p","- Ngày, tháng, năm sinh.","g"],["p","- Số Chứng minh nhân dân hoặc số định danh cá nhân.","g"],["p","- Nơi ở hiện tại (trường hợp khác nơi đăng ký thường trú, tạm trú).","g"],["p","- Chức vụ đang đảm nhiệm.","g"],["p","- Số điện thoại.","g"],["p","<b>4. Số vốn góp, nắm giữ cổ phần tại các tổ chức khác</b>","k"],["p","- Tên tổ chức, doanh nghiệp mà pháp nhân đang có vốn góp, nắm giữ cổ phần.","g"],["p","- Số vốn góp, nắm giữ cổ phần; tỷ lệ so với tổng vốn điều lệ của tổ chức, doanh nghiệp đó.","g"],["p","Sau khi nghiên cứu Điều lệ Quỹ tín dụng nhân dân……………… và các quy định của pháp luật có liên quan, (tên pháp nhân) đăng ký tham gia làm thành viên Quỹ tín dụng nhân dân……………… với số tiền góp vốn là ……………………đồng.",""],["p","<b>5. Cam kết</b>","k"],["p","a) Góp đủ vốn đã đăng ký và góp vốn đúng thời hạn theo quy định của Quỹ tín dụng nhân dân ……………………;","d"],["p","b) Có đủ năng lực tài chính để góp vốn vào Quỹ tín dụng nhân dân……………… theo quy định của Ngân hàng Nhà nước; Không sử dụng vốn ủy thác, vốn vay của các tổ chức, cá nhân khác để góp vốn; Chịu trách nhiệm về tính hợp pháp của vốn góp vào quỹ tín dụng nhân dân;","d"],["p","c) Tuân thủ các quy định trong Điều lệ Quỹ tín dụng nhân dân…………………… và các quy định của pháp luật có liên quan;","d"],["p","d) Chịu trách nhiệm về tính trung thực, chính xác của những hồ sơ gửi kèm.","d"],["p","<b>Người đại diện theo pháp luật </b><i>(Ký, ghi rõ, họ tên, chức vụ và đóng dấu)</i>",""]]}],"phu_luc":true},{"id":"c12","title":"Phụ lục số 06","articles":[{"id":"pl-12","so":"","ten":"","nd":[["p","<i>(Ban h à nh k è m theo Thông tư số</i> /<i>2023<i>/TT-NHNN </i> ngày / /2023 của </i>",""],["p","<i>Thống đốc Ngân hàng Nhà nước Việt Nam)</i>",""]]}],"phu_luc":true},{"id":"c13","title":"Phụ lục số 04 — Mẫu Sơ yếu lý lịch — CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM Độc lập - Tự do - Hạnh phúc","articles":[{"id":"pl-13","so":"","ten":"","nd":[["p","Ảnh màu (4x6) đóng dấu giáp lai của cơ quan xác nhận lý lịch",""],["p","<b>SƠ YẾU LÝ LỊCH</b>",""],["p","<b>1. Về bản thân</b>","k"],["p","- Họ và tên khai sinh.","g"],["p","- Họ và tên thường gọi.","g"],["p","- Bí danh (nếu có).","g"],["p","- Ngày, tháng, năm sinh.","g"],["p","- Số Chứng minh nhân dân hoặc số định danh cá nhân, nơi ở hiện tại (trường hợp khác nơi đăng ký thường trú, tạm trú).","g"],["p","- Tên, địa chỉ pháp nhân; số vốn góp, tỷ lệ vốn góp (trường hợp là người đại diện vốn góp của pháp nhân).","g"],["p","<b>2. Trình độ học vấn:</b>","k"],["p","- Giáo dục phổ thông.","g"],["p","- Học hàm, học vị (nêu rõ tên, địa chỉ trường; chuyên ngành học; thời gian học; bằng cấp (liệt kê đầy đủ các bằng cấp).","g"],["p","<b>3. Quá trình công tác:</b>","k"],["p","- Nghề nghiệp, đơn vị, chức vụ công tác từ năm 18 tuổi đến nay(1):","g"],["t","<table><tr><td><b>STT</b></td><td><b>Thời gian (từ tháng/năm đến tháng/năm)(2)</b></td><td><b>Đơn vị công tác</b></td><td><b>Chức vụ</b></td><td><b>Lĩnh vực hoạt động của doanh nghiệp và nhiệm vụ được giao</b></td><td><b>Ghi chú(3)</b></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td></tr></table>",""],["p","- Khen thưởng, kỷ luật, trách nhiệm theo kết luận thanh tra dẫn đến việc tổ chức tín dụng, chi nhánh ngân hàng nước ngoài bị xử phạt vi phạm hành chính(4).","g"],["p","<b>4. Mối quan hệ:</b>","k"],["t","<table><tr><td><b>STT</b></td><td><b>Họ và tên</b></td><td><b><i>Số Chứng minh nhân dân hoặc số định danh cá nhân</i></b></td><td><b>Mối quan hệ với người khai(5)</b></td><td><b>Chức vụ tại Quỹ tín dụng nhân dân…</b></td></tr><tr><td>1</td><td>Nguyễn Văn A</td><td></td><td>Anh ruột</td><td></td></tr><tr><td>2</td><td>Nguyễn Thị B</td><td></td><td>Vợ</td><td></td></tr></table>",""],["p","<b>5. Năng lực hành vi dân sự(6)</b>","k"],["p","<b>6. Cam kết trước pháp luật</b>","k"],["p","Tôi cam kết:",""],["p","- Không vi phạm các quy định của pháp luật trong lĩnh vực tiền tệ và ngân hàng.","g"],["p","- Đáp ứng tiêu chuẩn, điều kiện để giữ chức danh……… tại Quỹ tín dụng nhân dân……..","g"],["p","- Thông báo cho quỹ tín dụng nhân dân về bất kỳ thay đổi nào liên quan đến nội dung bản khai trên phát sinh trong thời gian Ngân hàng Nhà nước chi nhánh đang xem xét đề nghị của Quỹ tín dụng nhân dân…………...","g"],["p","- Các thông tin cá nhân tôi cung cấp cho Quỹ tín dụng nhân dân:………… để trình Ngân hàng Nhà nước chi nhánh xem xét, chấp thuận dự kiến nhân sự là đúng sự thật.","g"],["p","Tôi xin chịu hoàn toàn trách nhiệm đối với bất kỳ thông tin nào không đúng với sự thật tại bản khai này.",""],["p","<i>..., ngày... tháng... năm .... </i><b>Người khai </b><i>(Ký, ghi rõ họ tên)(7)</i>",""],["p","<b><i>Ghi chú:</i></b>",""],["p","<i>Người khai phải kê khai đầy đủ thông tin theo yêu cầu và chịu trách nhiệm trước pháp luật và quỹ tín dụng nhân dân về tính đầy đủ, chính xác, trung thực của hồ sơ, trường hợp không phát sinh thì ghi rõ không có.</i>",""],["p","<i>(1) Người khai phải kê khai đầy đủ công việc, đơn vị công tác, các chức vụ đã và đang nắm giữ.</i>",""],["p","<i>(2) Phải đảm bảo tính liên tục về mặt thời gian.</i>",""],["p","<i>(3) Ghi chú nếu đơn vị công tác thuộc các trường hợp sau:</i>",""],["p","(i) Doanh nghiệp mà Nhà nước sở hữu từ 50% vốn điều lệ trở lên;",""],["p","(ii) Đơn vị theo quy định tại điểm e khoản 2 Điều 33 Luật Các tổ chức tín dụng (đã sửa đổi, bổ sung);",""],["p","(iii) Đơn vị theo quy định tại điểm c, d khoản 1 Điều 33 Luật Các tổ chức tín dụng (đã sửa đổi, bổ sung).",""],["p","<i>(4) Ghi cụ thể nếu nhân sự thuộc trường hợp nêu tại điểm đ, h khoản 1 Điều 33 Luật Các tổ chức tín dụng (đã sửa đổi, bổ sung).</i>",""],["p","<i>(5) Căn cứ mối quan hệ thực tế của người có liên quan thuộc trường hợp cụ thể theo quy định tại khoản 28 Điều 4 Luật Các tổ chức tín dụng (đã sửa đổi, bổ sung) và quy định có liên quan để điền vào cột này.</i>",""],["p","<i>(6) Ghi cụ thể: Đầy đủ/Hạn chế/Mất năng lực hành vi dân sự.</i>",""],["p","<i>(7) Chữ ký phải được chứng thực theo quy định của pháp luật.</i>",""],["p","<i>Ngoài những nội dung cơ bản trên, người khai có thể bổ sung các nội dung khác nếu thấy cần thiết.</i>",""]]}],"phu_luc":true},{"id":"c14","title":"Phụ lục số 07","articles":[{"id":"pl-14","so":"","ten":"","nd":[["p","<i>(Ban h à nh k è m theo Thông tư số</i> /<i>2023<i>/TT-NHNN </i> ngày / /2023 của </i>",""],["p","<i>Thống đốc Ngân hàng Nhà nước Việt Nam)</i>",""]]}],"phu_luc":true},{"id":"c15","title":"Phụ lục số 02 — Mẫu Sơ yếu lý lịch — CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM Độc lập - Tự do - Hạnh phúc","articles":[{"id":"pl-15","so":"","ten":"","nd":[["p","Ảnh màu (4x6) đóng dấu giáp lai của cơ quan xác nhận lý lịch",""],["p","<b>SƠ YẾU LÝ LỊCH</b>",""],["p","<b>1. Về bản thân</b>","k"],["p","- Họ và tên khai sinh.","g"],["p","- Họ và tên thường gọi.","g"],["p","- Bí danh (nếu có).","g"],["p","- Ngày, tháng, năm sinh.","g"],["p","- Số Chứng minh nhân dân hoặc số định danh cá nhân, nơi ở hiện tại (trường hợp khác nơi đăng ký thường trú, tạm trú) đối với cá nhân có quốc tịch Việt Nam.","g"],["p","- Số hộ chiếu hoặc giấy tờ có giá trị thay thế hộ chiếu, ngày cấp, nơi cấp, quốc tịch/các quốc tịch (nếu có), nơi ở hiện tại đối với cá nhân không có quốc tịch Việt Nam.","g"],["p","- Tên, địa chỉ pháp nhân mà mình đại diện; số vốn góp và tỷ lệ vốn góp (trường hợp thành viên góp vốn là pháp nhân).","g"],["p","<b>2. Trình độ học vấn:</b>","k"],["p","- Giáo dục phổ thông.","g"],["p","- Học hàm, học vị (nêu rõ tên, địa chỉ trường; chuyên ngành học; thời gian học; bằng cấp (liệt kê đầy đủ các bằng cấp).","g"],["p","<b>3. Quá trình công tác:</b>","k"],["p","- Nghề nghiệp, đơn vị, chức vụ công tác từ năm 18 tuổi đến nay(1):","g"],["t","<table><tr><td><b>STT</b></td><td><b>Thời gian (từ tháng/năm đến tháng/năm)(2)</b></td><td><b>Đơn vị công tác</b></td><td><b>Chức vụ</b></td><td><b>Lĩnh vực hoạt động của doanh nghiệp và nhiệm vụ được giao</b></td><td><b>Ghi chú(3)</b></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td></tr></table>",""],["p","- Khen thưởng, kỷ luật, trách nhiệm theo kết luận thanh tra dẫn đến việc tổ chức tín dụng, chi nhánh ngân hàng nước ngoài bị xử phạt vi phạm hành chính(4).","g"],["p","<b>4. Năng lực hành vi dân sự(5)</b>","k"],["p","<b>5. Cam kết trước pháp luật</b>","k"],["p","Tôi cam kết:",""],["p","- Không vi phạm các quy định của pháp luật trong lĩnh vực tiền tệ và ngân hàng.","g"],["p","- Đáp ứng tiêu chuẩn, điều kiện để giữ chức danh…………………. tại Tổ chức tài chính vi mô………(6)","g"],["p","- Thông báo cho Tổ chức tài chính vi mô……… về bất kỳ thay đổi nào liên quan đến nội dung bản khai trên phát sinh trong thời gian Ngân hàng Nhà nước Việt Nam đang xem xét đề nghị của Tổ chức tài chính vi mô………………(7)","g"],["p","- Các thông tin cá nhân tôi cung cấp cho tổ chức tài chính vi mô là đúng sự thật. Tôi xin chịu hoàn toàn trách nhiệm đối với bất kỳ thông tin nào không đúng với sự thật tại bản khai này.","g"],["p","<i>..., ngày... tháng... năm .... </i><b>Người khai </b><i>(Ký, ghi rõ họ tên)(8)</i>",""],["p","<b><i>Ghi chú:</i></b>",""],["p","<i>Người khai phải kê khai đầy đủ thông tin theo yêu cầu và chịu trách nhiệm trước pháp luật và tổ chức tài chính vi mô về tính đầy đủ, chính xác, trung thực của hồ sơ, trường hợp không phát sinh thì ghi rõ không có.</i>",""],["p","<i>(1) Người khai phải kê khai đầy đủ công việc, đơn vị công tác, các chức vụ đã và đang nắm giữ.</i>",""],["p","<i>(2) Phải đảm bảo tính liên tục về mặt thời gian.</i>",""],["p","<i>(3) Ghi chú nếu đơn vị công tác thuộc các trường hợp sau:</i>",""],["p","(i) Doanh nghiệp mà Nhà nước sở hữu từ 50% vốn điều lệ trở lên;",""],["p","(ii) Đơn vị theo quy định tại điểm e khoản 2 Điều 33 Luật Các tổ chức tín dụng (đã sửa đổi, bổ sung);",""],["p","(iii) Đơn vị theo quy định tại điểm c, d khoản 1 Điều 33 Luật Các tổ chức tín dụng (đã sửa đổi, bổ sung).",""],["p","<i>(4) Ghi cụ thể nếu nhân sự thuộc trường hợp nêu tại điểm đ, h khoản 1 Điều 33 Luật Các tổ chức tín dụng (đã sửa đổi, bổ sung).</i>",""],["p","<i>(5) Ghi cụ thể: </i>",""],["p","<i>(i) Đầy đủ/Hạn chế/Mất năng lực hành vi dân sự.</i>",""],["p","(ii) Thông tin về cấm đảm nhiệm chức vụ, thành lập, quản lý doanh nghiệp, hợp tác xã (đối với trường hợp phiếu lý lịch tư pháp hoặc văn bản có giá trị tương đương do cơ quan có thẩm quyền nước ngoài cấp không có thông tin này).",""],["p","<i>(6), (7): Cam kết khi khai thông tin để Ngân hàng Nhà nước Việt Nam xem xét chấp thuận danh sách nhân sự dự kiến.</i>",""],["p","<i>(8) Chữ ký phải được chứng thực theo quy định của pháp luật.</i>",""],["p","<i>Ngoài những nội dung cơ bản trên, người khai có thể bổ sung các nội dung khác nếu thấy cần thiết.</i>",""]]}],"phu_luc":true},{"id":"c16","title":"Phụ lục số 08a — B ảng kê khai người có liên quan sử dụng khi — đề nghị chấp thuận danh sách nhân sự dự kiến","articles":[{"id":"pl-16","so":"","ten":"","nd":[["p","<i>(Ban hành kèm theo Thông tư số</i> /<i>2023<i>/TT-NHNN ngày / /2023 của </i></i>",""],["p","<i>Thống đốc Ngân hàng Nhà nước Việt Nam)</i>",""],["p","<b>CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM Độc lập - Tự do - Hạnh phúc </b>",""],["p","<b>BẢNG KÊ KHAI NGƯỜI CÓ LIÊN QUAN</b>",""],["p","Kính gửi: Ngân hàng Nhà nước Việt Nam",""],["t","<table><tr><td><b>STT</b></td><td><b>Người khai và “người có liên quan” của người khai</b></td><td><b>Số CMND/số định danh cá nhân /số Hộ chiếu (1)</b></td><td><b>Mối quan hệ với người khai(2)</b></td><td><b>Chức vụ tại tổ chức tài chính vi mô đề nghị</b></td></tr><tr><td><b>I</b></td><td colspan=\"4\"><b>Người kê khai</b></td></tr><tr><td>1</td><td>Nguyễn Văn A</td><td></td><td>Người khai</td><td></td></tr><tr><td><b>II</b></td><td colspan=\"4\"><b>Người có liên quan</b></td></tr><tr><td>2</td><td>Nguyễn Thị B</td><td></td><td>Vợ</td><td></td></tr></table>",""],["p","Tôi cam kết các thông tin cung cấp trên đây là đúng sự thật. Tôi xin chịu trách nhiệm trước pháp luật về tính đầy đủ, trung thực, chính xác của các thông tin kê khai nêu trên.",""],["p","<i>…, ngày … tháng … năm…..</i>",""],["p","<b>Người khai</b>",""],["p","<i>(Ký, ghi rõ họ tên)(3)</i>",""],["p","<b>Ghi chú:</b>",""],["p","<i>(1) Số Chứng minh nhân dân hoặc số định danh cá nhân đối với cá nhân có quốc tịch Việt Nam; số hộ chiếu hoặc giấy tờ có giá trị thay thế hộ chiếu đối với cá nhân không có quốc tịch Việt Nam.</i>",""],["p","<i>(2) Căn cứ mối quan hệ thực tế của người có liên quan thuộc trường hợp cụ thể theo quy định tại khoản 28 Điều 4 Luật Các tổ chức tín dụng (đã sửa đổi, bổ sung) và quy định có liên quan để điền vào cột này.</i>",""],["p","<i>(3) Chữ ký phải được chứng thực theo quy định của pháp luật.</i>",""],["p","<b>Ngoài những nội dung tối thiểu nêu trên, người khai có thể bổ sung các nội dung khác nếu thấy cần thiết.</b>",""]]}],"phu_luc":true},{"id":"c17","title":"Phụ lục số 08b — B ảng kê khai người có liên quan sử dụng khi — đề nghị xem xét điều kiện thành viên góp vốn là cá nhân","articles":[{"id":"pl-17","so":"","ten":"","nd":[["p","<i>(Ban hành kèm theo Thông tư số</i> /<i>2023<i>/TT-NHNN ngày / /2023 của </i></i>",""],["p","<i>Thống đốc Ngân hàng Nhà nước Việt Nam)</i>",""],["p","<b>CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM Độc lập - Tự do - Hạnh phúc </b>",""],["p","<b>BẢNG KÊ KHAI NGƯỜI CÓ LIÊN QUAN</b>",""],["p","Kính gửi: Ngân hàng Nhà nước Việt Nam",""],["t","<table><tr><td rowspan=\"2\"><b>STT</b></td><td rowspan=\"2\"><b>Người khai và “người có liên quan” của người khai</b></td><td rowspan=\"2\"><b>Số CMND/</b><br><b>số định danh cá nhân/số</b><br><b>Hộ chiếu; Số Giấy phép(1)</b></td><td rowspan=\"2\"><b>Mối quan hệ với người khai(2)</b></td><td colspan=\"2\"><b>Đã tham gia góp vốn tổ chức tín dụng</b></td><td rowspan=\"2\"><b>Số vốn góp tại tổ chức tài chính vi mô khi thành lập</b></td></tr><tr><td><b>Tên, địa chỉ tổ chức tín dụng</b></td><td><b>Tỷ lệ góp vốn điều lệ của tổ chức tín dụng (%)</b></td></tr><tr><td><b>I</b></td><td colspan=\"5\"><b>Người kê khai</b></td><td></td></tr><tr><td><b>1</b></td><td><b>Nguyễn Văn A</b></td><td></td><td><b>Người khai</b></td><td></td><td></td><td></td></tr><tr><td><b>II.</b></td><td colspan=\"5\"><b>Người có liên quan/Tổ chức có liên quan</b></td><td></td></tr><tr><td><b>1</b></td><td><b>Nguyễn Thị B</b></td><td></td><td><b>Vợ</b></td><td></td><td></td><td></td></tr><tr><td><b>2</b></td><td><b>Công ty X</b></td><td></td><td><b>Là công ty do ông A là Chủ tịch HĐQT, Tổng giám đốc (Giám đốc),…</b></td><td></td><td></td><td></td></tr><tr><td>Tổng cộng</td><td></td><td></td><td></td><td></td><td>% (chi tiết từng tổ chức tín dụng)</td><td></td></tr></table>",""],["p","Tôi cam kết các thông tin cung cấp trên đây là đúng sự thật. Tôi xin chịu trách nhiệm trước pháp luật về tính đầy đủ và trung thực của các thông tin kê khai nêu trên.",""],["p","<i>...,ngày ... tháng ... năm …..</i> <b>Người khai(3)</b> <i>(ký, ghi rõ họ tên)</i>",""],["p","<b><i>Ghi chú:</i></b>",""],["p","<i>(1) Số Chứng minh nhân dân hoặc số định danh cá nhân đối với cá nhân có quốc tịch Việt Nam; số hộ chiếu hoặc giấy tờ có giá trị thay thế hộ chiếu đối với cá nhân không có quốc tịch Việt Nam; Số </i>Giấy phép thành lập hoặc Giấy chứng nhận đăng ký doanh nghiệp hoặc văn bản tương đương đối với tổ chức<i>.</i>",""],["p","(2) <i>Căn cứ mối quan hệ thực tế của người có liên quan thuộc trường hợp cụ thể theo quy định tại khoản 28 Điều 4 Luật Các tổ chức tín dụng (đã sửa đổi, bổ sung) và quy định có liên quan để điền vào cột này</i>.",""],["p","(3) Chữ ký phải được chứng thực theo quy định của pháp luật. Nếu là tổ chức, người ký tên người khai là đại diện hợp pháp của tổ chức và đóng dấu.",""],["p","<b>Ngoài những nội dung tối thiểu nêu trên, người khai có thể bổ sung các nội dung khác nếu thấy cần thiết.</b>",""]]}],"phu_luc":true},{"id":"c18","title":"Phụ lục số 09","articles":[{"id":"pl-18","so":"","ten":"","nd":[["p","<i>(Ban hành kèm theo Thông tư số</i> /<i>2023<i>/TT-NHNN ngày / /2023 của </i></i>",""],["p","<i>Thống đốc Ngân hàng Nhà nước Việt Nam)</i>",""]]}],"phu_luc":true},{"id":"c19","title":"Phụ lục số 08 — Mẫu Sơ yếu lý lịch","articles":[{"id":"pl-19","so":"","ten":"","nd":[["p","Ảnh màu (4x6) đóng dấu giáp lai của cơ quan xác nhận lý lịch",""],["p","<b>SƠ YẾU LÝ LỊCH</b>",""],["p","<b>1. Về bản thân</b>","k"],["p","- Họ và tên khai sinh.","g"],["p","- Họ và tên thường gọi.","g"],["p","- Bí danh (nếu có).","g"],["p","- Ngày, tháng, năm sinh.","g"],["p","- Số Chứng minh nhân dân hoặc số định danh cá nhân, nơi ở hiện tại (trường hợp khác nơi đăng ký thường trú, tạm trú).","g"],["p","- Tên, địa chỉ pháp nhân; số vốn góp, tỷ lệ vốn góp (trường hợp là người đại diện vốn góp của pháp nhân). Trường hợp là người được cử làm đại diện phần vốn hỗ trợ của Nhà nước tại Ngân hàng hợp tác xã, phải có thêm thông tin về tỷ lệ vốn góp được đại diện.","g"],["p","<b>2. Trình độ học vấn:</b>","k"],["p","- Giáo dục phổ thông.","g"],["p","- Học hàm, học vị (nêu rõ tên, địa chỉ trường; chuyên ngành học; thời gian học; bằng cấp (liệt kê đầy đủ các bằng cấp).","g"],["p","<b>3. Quá trình công tác:</b>","k"],["p","- Nghề nghiệp, đơn vị, chức vụ công tác từ năm 18 tuổi đến nay(1):","g"],["t","<table><tr><td><b>STT</b></td><td><b>Thời gian (từ tháng/năm đến tháng/năm)(2)</b></td><td><b>Đơn vị công tác</b></td><td><b>Chức vụ</b></td><td><b>Lĩnh vực hoạt động của doanh nghiệp và nhiệm vụ được giao</b></td><td><b>Ghi chú(3)</b></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td></tr></table>",""],["p","- Khen thưởng, kỷ luật, trách nhiệm theo kết luận thanh tra dẫn đến việc tổ chức tín dụng, chi nhánh ngân hàng nước ngoài bị xử phạt vi phạm hành chính(4).","g"],["p","<b>4. Năng lực hành vi dân sự(5)</b>","k"],["p","<b>5. Cam kết trước pháp luật</b>","k"],["p","Tôi cam kết:",""],["p","- Không vi phạm các quy định của pháp luật trong lĩnh vực tiền tệ và ngân hàng.","g"],["p","- Đáp ứng tiêu chuẩn, điều kiện để giữ chức danh…………. tại Ngân hàng hợp tác xã/Quỹ tín dụng nhân dân……….","g"],["p","- Thông báo cho tổ chức tín dụng là hợp tác xã về bất kỳ thay đổi nào liên quan đến nội dung bản khai trên phát sinh trong thời gian Ngân hàng Nhà nước Việt Nam/Ngân hàng Nhà nước chi nhánh đang xem xét đề nghị của Ngân hàng hợp tác xã/Quỹ tín dụng nhân dân………..","g"],["p","- Các thông tin cá nhân tôi cung cấp cho Ngân hàng hợp tác xã/Quỹ tín dụng nhân dân: ……………………… để trình Ngân hàng Nhà nước Việt Nam/Ngân hàng Nhà nước chi nhánh xem xét, chấp thuận dự kiến nhân sự là đúng sự thật.","g"],["p","Tôi xin chịu hoàn toàn trách nhiệm đối với bất kỳ thông tin nào không đúng với sự thật tại bản khai này.",""],["p","<i>..., ngày... tháng... năm .... </i><b>Người khai </b><i>(Ký, ghi rõ họ tên)(6)</i>",""],["p","<b><i>Ghi chú:</i></b>",""],["p","<i>Người khai phải kê khai đầy đủ thông tin theo yêu cầu và chịu trách nhiệm trước pháp luật và tổ chức tín dụng là hợp tác xã về tính đầy đủ, chính xác, trung thực của hồ sơ, trường hợp không phát sinh thì ghi rõ không có.</i>",""],["p","<i>(1) Người khai phải kê khai đầy đủ công việc, đơn vị công tác, các chức vụ đã và đang nắm giữ.</i>",""],["p","<i>(2) Phải đảm bảo tính liên tục về mặt thời gian.</i>",""],["p","<i>(3) Ghi chú nếu đơn vị công tác thuộc các trường hợp sau:</i>",""],["p","(i) Doanh nghiệp mà Nhà nước sở hữu từ 50% vốn điều lệ trở lên;",""],["p","(ii) Đơn vị theo quy định tại điểm e khoản 2 Điều 33 Luật Các tổ chức tín dụng (đã sửa đổi, bổ sung);",""],["p","(iii) Đơn vị theo quy định tại điểm c, d khoản 1 Điều 33 Luật Các tổ chức tín dụng (đã sửa đổi, bổ sung).",""],["p","<i>(4) Ghi cụ thể nếu nhân sự thuộc trường hợp nêu tại điểm đ, h khoản 1 Điều 33 Luật Các tổ chức tín dụng (đã sửa đổi, bổ sung).</i>",""],["p","<i>(5) Ghi cụ thể: Đầy đủ/Hạn chế/Mất năng lực hành vi dân sự.</i>",""],["p","<i>(6) Chữ ký phải được chứng thực theo quy định của pháp luật.</i>",""],["p","<i>Ngoài những nội dung cơ bản trên, người khai có thể bổ sung các nội dung khác nếu thấy cần thiết.</i>",""]]}],"phu_luc":true},{"id":"c20","title":"Phụ lục số 10","articles":[{"id":"pl-20","so":"","ten":"","nd":[["p","<i>(Ban hành kèm theo Thông tư số</i> /<i>2023<i>/TT-NHNN ngày / /2023 của </i></i>",""],["p","<i>Thống đốc Ngân hàng Nhà nước Việt Nam)</i>",""]]}],"phu_luc":true},{"id":"c21","title":"Phụ lục số 09 — Bảng kê khai người có liên quan — CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM Độc lập - Tự do - Hạnh phúc","articles":[{"id":"pl-21","so":"","ten":"","nd":[["p","<b>BẢNG KÊ KHAI NGƯỜI CÓ LIÊN QUAN</b>",""],["p","Kính gửi: Ngân hàng Nhà nước Việt Nam/Ngân hàng Nhà nước chi nhánh….",""],["t","<table><tr><td><b>STT</b></td><td><b>Người khai và “người có liên quan” của người khai</b></td><td><b>Số Chứng minh nhân dân hoặc số định danh cá nhân; số hộ chiếu hoặc giấy tờ có giá trị thay thế hộ chiếu (đối với người không có quốc tịch Việt Nam)</b></td><td><b>Mối quan hệ với người khai(1)</b></td><td><b>Chức vụ tại ngân hàng hợp tác xã/Quỹ tín dụng nhân dân….</b></td></tr><tr><td><b>I</b></td><td colspan=\"4\"><b>Người kê khai</b></td></tr><tr><td>1</td><td>Nguyễn Văn A</td><td></td><td>Người khai</td><td></td></tr><tr><td><b>II</b></td><td colspan=\"4\"><b>Người có liên quan</b></td></tr><tr><td>2</td><td>Nguyễn Thị B</td><td></td><td>Vợ</td><td></td></tr></table>",""],["p","Tôi cam kết các thông tin cung cấp trên đây là đúng sự thật. Tôi xin chịu trách nhiệm trước pháp luật về tính đầy đủ, trung thực, chính xác của các thông tin kê khai nêu trên.",""],["p","<i>…, ngày … tháng … năm…..</i>",""],["p","<b>Người khai</b>",""],["p","<i>(Ký, ghi rõ họ tên)(2)</i>",""],["p","<b>Ghi chú:</b>",""],["p","<i>(1) Căn cứ mối quan hệ thực tế của người có liên quan thuộc trường hợp cụ thể theo quy định tại khoản 28 Điều 4 Luật Các tổ chức tín dụng (đã sửa đổi, bổ sung) và quy định có liên quan để điền vào cột này.</i>",""],["p","<i>(2) Chữ ký phải được chứng thực theo quy định của pháp luật.</i>",""],["p","<b>Ngoài những nội dung tối thiểu nêu trên, người khai có thể bổ sung các nội dung khác nếu thấy cần thiết.</b>",""]]}],"phu_luc":true},{"id":"c22","title":"Phụ lục số 11","articles":[{"id":"pl-22","so":"","ten":"","nd":[["p","<i>(Ban h à nh k è m theo Thông tư số</i> /<i>2023<i>/TT-NHNN </i> ngày / /2023 của </i>",""],["p","<i>Thống đốc Ngân hàng Nhà nước Việt Nam)</i>",""]]}],"phu_luc":true},{"id":"c23","title":"Phụ lục số 01 — Mẫu Sơ yếu lý lịch — CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM Độc lập - Tự do - Hạnh phúc","articles":[{"id":"pl-23","so":"","ten":"","nd":[["p","Ảnh màu (4x6) đóng dấu giáp lai của cơ quan xác nhận lý lịch",""],["p","<b>SƠ YẾU LÝ LỊCH</b>",""],["p","<b>1. Về bản thân</b>","k"],["p","- Họ và tên khai sinh.","g"],["p","- Họ và tên thường gọi.","g"],["p","- Bí danh (nếu có).","g"],["p","- Ngày, tháng, năm sinh.","g"],["p","- Số Chứng minh nhân dân hoặc số định danh cá nhân, nơi ở hiện tại (trường hợp khác nơi đăng ký thường trú, tạm trú) đối với cá nhân có quốc tịch Việt Nam.","g"],["p","- Số hộ chiếu hoặc giấy tờ có giá trị thay thế hộ chiếu, ngày cấp, nơi cấp, quốc tịch/các quốc tịch (nếu có), nơi ở hiện tại đối với cá nhân không có quốc tịch Việt Nam.","g"],["p","- Tên, địa chỉ pháp nhân mà mình đại diện; số vốn góp và tỷ lệ vốn góp (trường hợp thành viên góp vốn là pháp nhân).","g"],["p","<b>2. Trình độ học vấn:</b>","k"],["p","- Giáo dục phổ thông.","g"],["p","- Học hàm, học vị (nêu rõ tên, địa chỉ trường; chuyên ngành học; thời gian học; bằng cấp (liệt kê đầy đủ các bằng cấp).","g"],["p","<b>3. Quá trình công tác:</b>","k"],["p","- Nghề nghiệp, đơn vị, chức vụ công tác từ năm 18 tuổi đến nay(1):","g"],["t","<table><tr><td><b>STT</b></td><td><b>Thời gian (từ tháng/năm đến tháng/năm)(2)</b></td><td><b>Đơn vị công tác</b></td><td><b>Chức vụ</b></td><td><b>Lĩnh vực hoạt động của doanh nghiệp và nhiệm vụ được giao</b></td><td><b>Ghi chú(3)</b></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td></tr></table>",""],["p","- Khen thưởng, kỷ luật, trách nhiệm theo kết luận thanh tra dẫn đến việc tổ chức tín dụng, chi nhánh ngân hàng nước ngoài bị xử phạt vi phạm hành chính(4).","g"],["p","<b>4. Năng lực hành vi dân sự(5)</b>","k"],["p","<b>5. Cam kết trước pháp luật</b>","k"],["p","Tôi cam kết:",""],["p","- Không vi phạm các quy định của pháp luật trong lĩnh vực tiền tệ và ngân hàng.","g"],["p","- Các thông tin cá nhân tôi cung cấp cho Tổ chức tài chính vi mô……………… để trình Ngân hàng Nhà nước Việt Nam xem xét, chấp thuận mua bán, chuyển nhượng phần vốn góp là đúng sự thật.","g"],["p","Tôi xin chịu hoàn toàn trách nhiệm đối với bất kỳ thông tin nào không đúng với sự thật tại bản khai này.",""],["p","<i>..., ngày... tháng... năm .... </i><b>Người khai </b><i>(Ký, ghi rõ họ tên)(6)</i>",""],["p","<b><i>Ghi chú:</i></b>",""],["p","<i>Người khai phải kê khai đầy đủ thông tin theo yêu cầu và chịu trách nhiệm trước pháp luật và tổ chức tài chính vi mô về tính đầy đủ, chính xác, trung thực của hồ sơ, trường hợp không phát sinh thì ghi rõ không có.</i>",""],["p","<i>(1) Người khai phải kê khai đầy đủ công việc, đơn vị công tác, các chức vụ đã và đang nắm giữ.</i>",""],["p","<i>(2) Phải đảm bảo tính liên tục về mặt thời gian.</i>",""],["p","<i>(3) Ghi chú nếu đơn vị công tác thuộc các trường hợp sau:</i>",""],["p","(i) Doanh nghiệp mà Nhà nước sở hữu từ 50% vốn điều lệ trở lên;",""],["p","(ii) Đơn vị theo quy định tại điểm e khoản 2 Điều 33 Luật Các tổ chức tín dụng (đã sửa đổi, bổ sung);",""],["p","(iii) Đơn vị theo quy định tại điểm c, d khoản 1 Điều 33 Luật Các tổ chức tín dụng (đã sửa đổi, bổ sung).",""],["p","<i>(4) Ghi cụ thể nếu nhân sự thuộc trường hợp nêu tại điểm đ, h khoản 1 Điều 33 Luật Các tổ chức tín dụng (đã sửa đổi, bổ sung).</i>",""],["p","<i>(5) Ghi cụ thể: </i>",""],["p","<i>(i) Đầy đủ/Hạn chế/Mất năng lực hành vi dân sự.</i>",""],["p","(ii) Thông tin về cấm đảm nhiệm chức vụ, thành lập, quản lý doanh nghiệp, hợp tác xã (đối với trường hợp phiếu lý lịch tư pháp hoặc văn bản có giá trị tương đương do cơ quan có thẩm quyền nước ngoài cấp không có thông tin này).",""],["p","<i>(6) Chữ ký phải được chứng thực theo quy định của pháp luật.</i>",""],["p","<i>Ngoài những nội dung cơ bản trên, người khai có thể bổ sung các nội dung khác nếu thấy cần thiết.</i>",""]]}],"phu_luc":true},{"id":"c24","title":"Phụ lục số 12","articles":[{"id":"pl-24","so":"","ten":"","nd":[["p","<i>(Ban hành kèm theo Thông tư số</i> /<i>2023<i>/TT-NHNN ngày / /2023 của </i></i>",""],["p","<i>Thống đốc Ngân hàng Nhà nước Việt Nam)</i>",""]]}],"phu_luc":true},{"id":"c25","title":"Phụ lục số 02 — Bảng kê khai người có liên quan — CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM Độc lập - Tự do - Hạnh phúc","articles":[{"id":"pl-25","so":"","ten":"","nd":[["p","<b>BẢNG KÊ KHAI NGƯỜI CÓ LIÊN QUAN</b>",""],["p","Kính gửi: Ngân hàng Nhà nước Việt Nam",""],["t","<table><tr><td rowspan=\"2\"><b>STT</b></td><td rowspan=\"2\"><b>Người khai và “người có liên quan” của người khai</b></td><td rowspan=\"2\"><b>Số CMND/</b><br><b>số định danh cá nhân/số Hộ chiếu; Số Giấy phép(1)</b></td><td rowspan=\"2\"><b>Mối quan hệ với người khai(2)</b></td><td colspan=\"2\"><b>Đã tham gia góp vốn tổ chức tín dụng</b></td><td rowspan=\"2\"><b>Số vốn góp tại tổ chức tài chính vi mô khi thành lập</b></td></tr><tr><td><b>Tên, địa chỉ tổ chức tín dụng</b></td><td><b>Tỷ lệ góp vốn điều lệ của tổ chức tín dụng (%)</b></td></tr><tr><td><b>I</b></td><td colspan=\"5\"><b>Người kê khai/tổ chức khai</b></td><td></td></tr><tr><td><b>1</b></td><td><b>Nguyễn Văn A/</b><br><b>Tổ chức A</b></td><td></td><td><b>Người khai/</b><br><b>Tổ chức khai</b></td><td></td><td></td><td></td></tr><tr><td><b>II.</b></td><td colspan=\"5\"><b>Người có liên quan/tổ chức có liên quan</b></td><td></td></tr><tr><td><b>1.</b></td><td><b>Nguyễn Thị B/</b><br><b>Tổ chức B</b></td><td></td><td><b>Vợ/</b><br><b>Công ty con</b></td><td></td><td></td><td></td></tr><tr><td>Tổng cộng</td><td></td><td></td><td></td><td></td><td>% (chi tiết từng tổ chức tín dụng)</td><td></td></tr></table>",""],["p","Tôi cam kết các thông tin cung cấp trên đây là đúng sự thật. Tôi xin chịu trách nhiệm trước pháp luật về tính đầy đủ và trung thực của các thông tin kê khai nêu trên.",""],["p","<i>...,ngày ... tháng ... năm …..</i> <b>Người khai(3)</b> <i>(ký, ghi rõ họ tên)</i>",""],["p","<b><i>Ghi chú:</i></b>",""],["p","<i>(1) Số Chứng minh nhân dân hoặc số định danh cá nhân đối với cá nhân có quốc tịch Việt Nam; số hộ chiếu hoặc giấy tờ có giá trị thay thế hộ chiếu đối với cá nhân không có quốc tịch Việt Nam; Số </i>Giấy phép thành lập hoặc Giấy chứng nhận đăng ký doanh nghiệp hoặc văn bản tương đương đối với tổ chức<i>.</i>",""],["p","(2) <i>Căn cứ mối quan hệ thực tế của người có liên quan thuộc trường hợp cụ thể theo quy định tại khoản 28 Điều 4 Luật Các tổ chức tín dụng (đã sửa đổi, bổ sung) và quy định có liên quan để điền vào cột này</i>.",""],["p","(3) Chữ ký phải được chứng thực theo quy định của pháp luật. Nếu là tổ chức, người ký tên người khai là đại diện hợp pháp của tổ chức và đóng dấu.",""],["p","<b>Ngoài những nội dung tối thiểu nêu trên, người khai có thể bổ sung các nội dung khác nếu thấy cần thiết.</b>",""]]}],"phu_luc":true},{"id":"c26","title":"Phụ lục số 13","articles":[{"id":"pl-26","so":"","ten":"","nd":[["p","<i>(Ban hành kèm theo Thông tư số</i> /<i>2023<i>/TT-NHNN ngày / /2023 của </i></i>",""],["p","<i>Thống đốc Ngân hàng Nhà nước Việt Nam)</i>",""]]}],"phu_luc":true},{"id":"c27","title":"Phụ lục số 02 — Mẫu Sơ yếu lý lịch","articles":[{"id":"pl-27","so":"","ten":"","nd":[["p","Ảnh màu (4x6) đóng dấu giáp lai của cơ quan xác nhận lý lịch",""],["p","<b>SƠ YẾU LÝ LỊCH</b>",""],["p","<b>1. Về bản thân</b>","k"],["p","- Họ và tên khai sinh.","g"],["p","- Họ và tên thường gọi.","g"],["p","- Bí danh (nếu có).","g"],["p","- Ngày, tháng, năm sinh.","g"],["p","- Số Chứng minh nhân dân hoặc số định danh cá nhân, nơi ở hiện tại (trường hợp khác nơi đăng ký thường trú, tạm trú).","g"],["p","- Tên, địa chỉ pháp nhân; số vốn góp, tỷ lệ vốn góp (trường hợp là người đại diện vốn góp của pháp nhân).","g"],["p","<b>2. Trình độ học vấn:</b>","k"],["p","- Giáo dục phổ thông.","g"],["p","- Học hàm, học vị (nêu rõ tên, địa chỉ trường; chuyên ngành học; thời gian học; bằng cấp (liệt kê đầy đủ các bằng cấp).","g"],["p","<b>3. Quá trình công tác:</b>","k"],["p","- Nghề nghiệp, đơn vị, chức vụ công tác từ năm 18 tuổi đến nay(1):","g"],["t","<table><tr><td><b>STT</b></td><td><b>Thời gian (từ tháng/năm đến tháng/năm)(2)</b></td><td><b>Đơn vị công tác</b></td><td><b>Chức vụ</b></td><td><b>Lĩnh vực hoạt động của doanh nghiệp và nhiệm vụ được giao</b></td><td><b>Ghi chú(3)</b></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td></tr></table>",""],["p","- Khen thưởng, kỷ luật, trách nhiệm theo kết luận thanh tra dẫn đến việc tổ chức tín dụng, chi nhánh ngân hàng nước ngoài bị xử phạt vi phạm hành chính(4).","g"],["p","<b>4. Năng lực hành vi dân sự(5)</b>","k"],["p","<b>5. Cam kết trước pháp luật</b>","k"],["p","Tôi cam kết:",""],["p","- Không vi phạm các quy định của pháp luật trong lĩnh vực tiền tệ và ngân hàng.","g"],["p","- Đáp ứng tiêu chuẩn, điều kiện để giữ chức danh…………….tại Quỹ tín dụng nhân dân…….","g"],["p","- Thông báo cho quỹ tín dụng nhân dân về bất kỳ thay đổi nào liên quan đến nội dung bản khai trên phát sinh trong thời gian Ngân hàng Nhà nước chi nhánh đang xem xét đề nghị của Quỹ tín dụng nhân dân……………….","g"],["p","- Các thông tin cá nhân tôi cung cấp cho Quỹ tín dụng nhân dân………… để trình Ngân hàng Nhà nước chi nhánh xem xét, chấp thuận dự kiến nhân sự là đúng sự thật.","g"],["p","Tôi xin chịu hoàn toàn trách nhiệm đối với bất kỳ thông tin nào không đúng với sự thật tại bản khai này.",""],["p","<i>..., ngày... tháng... năm .... </i><b>Người khai </b><i>(Ký, ghi rõ họ tên)(6)</i>",""],["p","<b><i>Ghi chú:</i></b>",""],["p","<i>Người khai phải kê khai đầy đủ thông tin theo yêu cầu và chịu trách nhiệm trước pháp luật và tổ chức tín dụng là hợp tác xã về tính đầy đủ, chính xác, trung thực của hồ sơ, trường hợp không phát sinh thì ghi rõ không có.</i>",""],["p","<i>(1) Người khai phải kê khai đầy đủ công việc, đơn vị công tác, các chức vụ đã và đang nắm giữ.</i>",""],["p","<i>(2) Phải đảm bảo tính liên tục về mặt thời gian.</i>",""],["p","<i>(3) Ghi chú nếu đơn vị công tác thuộc các trường hợp sau:</i>",""],["p","(i) Doanh nghiệp mà Nhà nước sở hữu từ 50% vốn điều lệ trở lên;",""],["p","(ii) Đơn vị theo quy định tại điểm e khoản 2 Điều 33 Luật Các tổ chức tín dụng (đã sửa đổi, bổ sung);",""],["p","(iii) Đơn vị theo quy định tại điểm c, d khoản 1 Điều 33 Luật Các tổ chức tín dụng (đã sửa đổi, bổ sung).",""],["p","<i>(4) Ghi cụ thể nếu nhân sự thuộc trường hợp nêu tại điểm đ, h khoản 1 Điều 33 Luật Các tổ chức tín dụng (đã sửa đổi, bổ sung).</i>",""],["p","<i>(5) Ghi cụ thể: Đầy đủ/Hạn chế/Mất năng lực hành vi dân sự.</i>",""],["p","<i>(6) Chữ ký phải được chứng thực theo quy định của pháp luật.</i>",""],["p","<i>Ngoài những nội dung cơ bản trên, người khai có thể bổ sung các nội dung khác nếu thấy cần thiết.</i>",""]]}],"phu_luc":true},{"id":"c28","title":"Phụ lục số 14","articles":[{"id":"pl-28","so":"","ten":"","nd":[["p","<i>(Ban hành kèm theo Thông tư số</i> /<i>2023<i>/TT-NHNN ngày / /2023 của </i></i>",""],["p","<i>Thống đốc Ngân hàng Nhà nước Việt Nam)</i>",""]]}],"phu_luc":true},{"id":"c29","title":"Phụ lục số 03 — Bảng kê khai người có liên quan — CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM Độc lập - Tự do - Hạnh phúc","articles":[{"id":"pl-29","so":"","ten":"","nd":[["p","<b>BẢNG KÊ KHAI NGƯỜI CÓ LIÊN QUAN</b>",""],["p","Kính gửi: Ngân hàng Nhà nước chi nhánh….",""],["t","<table><tr><td><b>STT</b></td><td><b>Người khai và “người có liên quan” của người khai</b></td><td><b>Số Chứng minh nhân dân hoặc số định danh cá nhân </b></td><td><b>Mối quan hệ với người khai(1)</b></td><td><b>Chức vụ tại quỹ tín dụng nhân dân đề nghị</b></td></tr><tr><td><b>I</b></td><td colspan=\"4\"><b>Người kê khai</b></td></tr><tr><td>1</td><td>Nguyễn Văn A</td><td></td><td>Người khai</td><td></td></tr><tr><td><b>II</b></td><td colspan=\"4\"><b>Người có liên quan</b></td></tr><tr><td>2</td><td>Nguyễn Thị B</td><td></td><td>Vợ</td><td></td></tr></table>",""],["p","Tôi cam kết các thông tin cung cấp trên đây là đúng sự thật. Tôi xin chịu trách nhiệm trước pháp luật về tính đầy đủ, trung thực, chính xác của các thông tin kê khai nêu trên.",""],["p","<i>…, ngày … tháng … năm…..</i>",""],["p","<b>Người khai</b>",""],["p","<i>(Ký, ghi rõ họ tên)(2)</i>",""],["p","<b>Ghi chú:</b>",""],["p","<i>(1) Căn cứ mối quan hệ thực tế của người có liên quan thuộc trường hợp cụ thể theo quy định tại khoản 28 Điều 4 Luật Các tổ chức tín dụng (đã sửa đổi, bổ sung) và quy định có liên quan để điền vào cột này.</i>",""],["p","<i>(2) Chữ ký phải được chứng thực theo quy định của pháp luật.</i>",""],["p","<b>Ngoài những nội dung tối thiểu nêu trên, người khai có thể bổ sung các nội dung khác nếu thấy cần thiết.</b>",""]]}],"phu_luc":true},{"id":"c30","title":"Phụ lục số 15","articles":[{"id":"pl-30","so":"","ten":"","nd":[["p","<i>(Ban hành kèm theo Thông tư số</i> /<i>2023<i>/TT-NHNN ngày / /2023 của </i></i>",""],["p","<i>Thống đốc Ngân hàng Nhà nước Việt Nam)</i>",""]]}],"phu_luc":true},{"id":"c31","title":"Phụ lục — Bảng kê khai người có liên quan — CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM Độc lập - Tự do - Hạnh phúc","articles":[{"id":"pl-31","so":"","ten":"","nd":[["p","<b>BẢNG KÊ KHAI NGƯỜI CÓ LIÊN QUAN</b>",""],["p","Kính gửi: Ngân hàng Nhà nước Việt Nam",""],["p","<b>1. Thông tin người kê khai</b>","k"],["p","<b>2. Người có liên quan</b>","k"],["t","<table><tr><td rowspan=\"2\"><b><i>STT</i></b></td><td rowspan=\"2\"><b><i>Người có liên quan</i></b></td><td rowspan=\"2\"><b><i>Mối quan hệ với người khai</i></b></td><td colspan=\"2\"><b><i>Tham gia góp vốn</i></b></td></tr><tr><td><b>Tên tổ chức tín dụng</b></td><td><b>Tỷ lệ sở hữu/vốn điều lệ của tổ chức tín dụng (%)</b></td></tr><tr><td>(1)</td><td>(2)</td><td>(3)</td><td>(4)</td><td>(5)</td></tr><tr><td>1.</td><td>Nguyễn Văn A</td><td>Người khai</td><td></td><td></td></tr><tr><td>2.</td><td>Nguyễn Thị B</td><td>Vợ</td><td></td><td></td></tr><tr><td>3.</td><td>Công ty X</td><td></td><td></td><td></td></tr><tr><td>…</td><td></td><td></td><td></td><td></td></tr><tr><td>Tổng cộng</td><td></td><td></td><td></td><td>% (chi tiết từng tổ chức tín dụng)</td></tr></table>",""],["p","Tôi cam kết nội dung Bảng kê khai trên đây là đúng sự thật, nếu có bất cứ sự không trung thực nào, tôi xin hoàn toàn chịu trách nhiệm trước pháp luật.",""],["p","<b> Người khai (6)</b>",""],["p","(<i>Ký, ghi rõ họ tên, đóng dấu (nếu có)</i>)",""],["p","<b>HƯỚNG DẪN KÊ KHAI THEO MẪU</b>",""],["p","1. Đối với phần kê khai Thông tin người kê khai: Kê khai thông tin của cá nhân, tổ chức, bên mua, bên nhận chuyển nhượng dự kiến là cổ đông lớn của tổ chức tín dụng phi ngân hàng.","k"],["p","a) Đối với cá nhân, kê khai các nội dung sau đây:","d"],["p","- Đối với cá nhân có quốc tịch Việt Nam: Họ và tên; ngày, tháng, năm sinh; số Chứng minh nhân dân hoặc số định danh cá nhân; nơi ở hiện tại (trường hợp khác nơi đăng ký thường trú, tạm trú).","g"],["p","- Đối với cá nhân không có quốc tịch Việt Nam: Họ và tên; ngày, tháng, năm sinh; số hộ chiếu hoặc giấy tờ có giá trị thay thế hộ chiếu, ngày cấp, nơi cấp; nơi ở hiện tại.","g"],["p","- Chức vụ được bầu, bổ nhiệm tại tổ chức tín dụng phi ngân hàng.","g"],["p","b) Đối với tổ chức, kê khai các nội dung sau đây:","d"],["p","- Tên tổ chức;","g"],["p","- Địa chỉ;","g"],["p","- Số Giấy phép thành lập hoặc số Giấy chứng nhận đăng ký doanh nghiệp hoặc văn bản tương đương, ngày cấp, nơi cấp.","g"],["p","2. Đối với phần kê khai Người có liên quan","k"],["p","2.1. Cột (2): Liệt kê người khai và tất cả người có liên quan của người khai là cá nhân, tổ chức, bên mua, bên nhận chuyển nhượng dự kiến là cổ đông lớn của tổ chức tín dụng phi ngân hàng, “Người có liên quan” tham chiếu theo quy định tại Luật các tổ chức tín dụng (đã được sửa đổi, bổ sung), quy định của Ngân hàng Nhà nước.",""],["p","2.2. Cột (3): Căn cứ mối quan hệ thực tế của người có liên quan ở cột (2) thuộc trường hợp cụ thể theo quy định tại Luật các tổ chức tín dụng (đã được sửa đổi, bổ sung) và các quy định có liên quan để điền vào cột (3).",""],["p","2.3. Cột (4): Ghi rõ tên, địa chỉ các tổ chức tín dụng đã tham gia góp vốn.",""],["p","2.4. Đối với phần kê khai tại (6): Nếu là tổ chức, người ký tên người khai là đại diện hợp pháp của tổ chức và đóng dấu.",""]]}],"phu_luc":true},{"id":"c32","title":"Phụ lục số 16","articles":[{"id":"pl-32","so":"","ten":"","nd":[["p","<i>(Ban hành kèm theo Thông tư số</i> /<i>2023<i>/TT-NHNN ngày / /2023 của </i></i>",""],["p","<i>Thống đốc Ngân hàng Nhà nước Việt Nam)</i>",""]]}],"phu_luc":true},{"id":"c33","title":"Phụ lục số 01 — Mẫu Sơ yếu lý lịch — CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM Độc lập - Tự do - Hạnh phúc","articles":[{"id":"pl-33","so":"","ten":"","nd":[["p","Ảnh màu (4x6) đóng dấu giáp lai của cơ quan xác nhận lý lịch",""],["p","<b>SƠ YẾU LÝ LỊCH(1)</b>",""],["p","<b>1. Về bản thân</b>","k"],["p","- Họ và tên khai sinh.","g"],["p","- Họ và tên thường gọi.","g"],["p","- Bí danh.","g"],["p","- Ngày, tháng, năm sinh.","g"],["p","- Số Chứng minh nhân dân hoặc số định danh cá nhân, nơi ở hiện tại (trường hợp khác nơi đăng ký thường trú, tạm trú) đối với cá nhân có quốc tịch Việt Nam.","g"],["p","- Số hộ chiếu hoặc giấy tờ có giá trị thay thế hộ chiếu, ngày cấp, nơi cấp, quốc tịch/các quốc tịch (nếu có), nơi ở hiện tại đối với cá nhân không có quốc tịch Việt Nam.","g"],["p","- Tên, địa chỉ của pháp nhân mà mình đại diện, tỷ lệ vốn góp được đại diện (trường hợp là người đại diện phần vốn góp của cổ đông hoặc thành viên góp vốn là pháp nhân hoặc là người được cử làm đại diện phần vốn góp của Nhà nước tại tổ chức tín dụng).","g"],["p","<b>2. Trình độ học vấn</b>","k"],["p","- Giáo dục phổ thông.","g"],["p","- Học hàm, học vị (nêu rõ tên, địa chỉ trường; chuyên ngành học; thời gian học; bằng cấp (liệt kê đầy đủ các bằng cấp).","g"],["p","<b>3. Quá trình công tác:</b>","k"],["p","- Nghề nghiệp, đơn vị, chức vụ công tác từ năm 18 tuổi đến nay (2).","g"],["t","<table><tr><td>STT</td><td>Thời gian<br>(từ tháng/năm đến tháng/năm) (3)</td><td>Đơn vị<br>công tác</td><td>Chức vụ(4)</td><td>Lĩnh vực hoạt động của doanh nghiệp và nhiệm vụ được giao</td><td>Ghi chú (5)</td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td></tr></table>",""],["p","- Khen thưởng, kỷ luật, trách nhiệm theo kết luận thanh tra dẫn đến việc tổ chức tín dụng, chi nhánh ngân hàng nước ngoài bị xử phạt vi phạm hành chính(6).","g"],["p","<b>4. Năng lực hành vi dân sự</b>(7)","k"],["p","<b>4a. Thông tin về cấm đảm nhiệm chức vụ, thành lập, quản lý doanh nghiệp, hợp tác xã (đối với trường hợp phiếu lý lịch tư pháp hoặc văn bản có giá trị tương đương do cơ quan có thẩm quyền nước ngoài cấp không có thông tin này)</b>.",""],["p","<b>5. Cam kết trước pháp luật</b>","k"],["p","Tôi cam kết:",""],["p","- Đáp ứng tiêu chuẩn, điều kiện để giữ chức danh … tại tổ chức tín dụng, chi nhánh ngân hàng nước ngoài.","g"],["p","- Không vi phạm các quy định của pháp luật trong lĩnh vực tiền tệ và ngân hàng.","g"],["p","- Thông báo cho tổ chức tín dụng, chi nhánh ngân hàng nước ngoài về bất kỳ thay đổi nào liên quan đến nội dung bản khai này phát sinh trong thời gian Ngân hàng Nhà nước đang xem xét đề nghị của ... (tên tổ chức tín dụng, chi nhánh ngân hàng nước ngoài).","g"],["p","- Các thông tin cá nhân Tôi cung cấp cho tổ chức tín dụng, chi nhánh ngân hàng nước ngoài để trình Ngân hàng Nhà nước xem xét, chấp thuận dự kiến nhân sự là đúng sự thật. Tôi xin chịu trách nhiệm trước pháp luật về tính đầy đủ, trung thực, chính xác của các thông tin kê khai nêu trên.","g"],["p","<i>…, ngày … tháng … năm …</i>",""],["p","<b> Chữ ký và họ tên đầy đủ của người khai</b>",""],["p","<i>(Ký, ghi rõ họ tên)(8)</i>",""],["p","<b>Ghi chú:</b>",""],["p","1. Người khai phải kê khai đầy đủ thông tin theo yêu cầu và chịu trách nhiệm trước pháp luật và tổ chức tín dụng, chi nhánh ngân hàng nước ngoài về tính đầy đủ, chính xác, trung thực của hồ sơ, trường hợp không phát sinh thì ghi rõ không có.","k"],["p","2. Người khai phải kê khai đầy đủ công việc, đơn vị công tác, các chức vụ đã và đang nắm giữ.","k"],["p","3. Phải đảm bảo tính liên tục về mặt thời gian.","k"],["p","4. Nêu rõ nếu nhân sự là người quản lý, người điều hành theo quy định của pháp luật và Điều lệ của tổ chức tín dụng, doanh nghiệp.","k"],["p","5. Ghi chú nếu đơn vị công tác thuộc các trường hợp sau:","k"],["p","a) Công ty con của tổ chức tín dụng;","d"],["p","b) Doanh nghiệp mà Nhà nước sở hữu từ 50% vốn điều lệ trở lên;","d"],["p","c) Đơn vị theo quy định tại điểm e khoản 2 Điều 33 Luật Các tổ chức tín dụng (đã sửa đổi, bổ sung);","d"],["p","d) Đơn vị theo quy định tại điểm c, d khoản 1 Điều 33 Luật Các tổ chức tín dụng (đã sửa đổi, bổ sung);","d"],["p","6. Ghi cụ thể nếu nhân sự thuộc trường hợp nêu tại điểm đ, h khoản 1 Điều 33 Luật Các tổ chức tín dụng (đã sửa đổi, bổ sung).","k"],["p","7. Ghi cụ thể: đầy đủ/hạn chế/mất năng lực hành vi dân sự.","k"],["p","8. Chữ ký phải được chứng thực theo quy định của pháp luật.","k"],["p","<b>(Ngoài những nội dung cơ bản trên, người khai có thể bổ sung các nội dung khác nếu thấy cần thiết)</b>",""]]}],"phu_luc":true},{"id":"c34","title":"Phụ lục số 17","articles":[{"id":"pl-34","so":"","ten":"","nd":[["p","<i>(Ban hành kèm theo Thông tư số</i> /<i>2023<i>/TT-NHNN ngày / /2023 của </i></i>",""],["p","<i>Thống đốc Ngân hàng Nhà nước Việt Nam)</i>",""]]}],"phu_luc":true},{"id":"c35","title":"Phụ lục số 02 — Bảng kê khai người có liên quan — CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM Độc lập - Tự do - Hạnh phúc","articles":[{"id":"pl-35","so":"","ten":"","nd":[["p","<b>BẢNG KÊ KHAI NGƯỜI CÓ LIÊN QUAN</b>",""],["p","Kính gửi: Ngân hàng Nhà nước Việt Nam",""],["t","<table><tr><td><b>STT</b></td><td><b>Người khai và “người có liên quan” của người khai</b></td><td><b>Mối quan hệ với người khai(1)</b></td><td><b>Số Chứng minh nhân dân/số định danh cá nhân (đối với cá nhân có quốc tịch Việt Nam) hoặc số hộ chiếu hoặc giấy tờ có giá trị thay thế hộ chiếu, ngày cấp (đối với cá nhân không có quốc tịch Việt Nam)</b></td><td><b>Chức vụ tại tổ chức tín dụng đề nghị</b></td><td><b>Chức vụ tại Công ty con của tổ chức tín dụng đề nghị</b></td><td><b>Tỷ lệ sở hữu cổ phần hoặc tỷ lệ vốn góp đại diện tại tổ chức tín dụng đề nghị (%)</b></td><td><b>…</b></td></tr><tr><td>1</td><td>Nguyễn Văn A</td><td>Người khai</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td>Nguyễn Thị B</td><td>Vợ</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>…</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr></table>",""],["p","Tôi cam kết các thông tin cung cấp trên đây là đúng sự thật. Tôi xin chịu trách nhiệm trước pháp luật về tính đầy đủ, trung thực, chính xác của các thông tin kê khai nêu trên.",""],["p","<i>…, ngày … tháng … năm…..</i>",""],["p","<b>Người khai</b>",""],["p","<i>(Ký, ghi rõ họ tên)(2)</i>",""],["p","<b>Ghi chú:</b>",""],["p","(1) Căn cứ mối quan hệ thực tế của người có liên quan tại cột (2) thuộc trường hợp cụ thể theo quy định tại khoản 28 Điều 4, khoản 2 Điều 62 Luật Các tổ chức tín dụng (đã sửa đổi, bổ sung) và quy định có liên quan để điền vào cột này.",""],["p","(2) Chữ ký phải được chứng thực theo quy định của pháp luật.",""],["p","<b><i>(Ngoài những nội dung tối thiểu nêu trên, người khai có thể bổ sung các nội dung khác nếu thấy cần thiết).</i></b>",""]]}],"phu_luc":true}],"chu_thich":{}};
